begin;

with seed(email, username, product_id, rating, body, created_at) as (
  values
    ('demo-review-1-001@shopupu.local','Marta K.',1,5,'Bought the black in M and the fleece inside is genuinely thick, not the thin scratchy kind you sometimes get. Sleeves run a little long which I actually like for winter, hood sits nicely without pulling at the neck. Washed it twice already and it kept its shape.','2026-01-18T09:14:22Z'),
    ('demo-review-1-002@shopupu.local','Denys',1,4,'Ordered grey in L for that oversized look and it delivers. Only thing is the hood feels a bit heavy when it''s down on my back, tugs at the collar a little. Otherwise comfortable enough to wear all day at home or running errands.','2026-01-24T18:47:03Z'),
    ('demo-review-1-003@shopupu.local','Julia Schmidt',1,3,'It''s fine. Runs pretty large even for an oversized style, I''m swimming in the L a bit. Fabric is nice and soft though, no complaints there. Might have been better in M for my frame.','2026-02-02T11:32:41Z'),
    ('demo-review-1-004@shopupu.local','tomasz.b',1,5,'Comfy, warm, good basic.','2026-02-09T20:03:55Z'),
    ('demo-review-1-005@shopupu.local','Oksana P.',1,4,'Got this for my brother in black, size L, and he wears it constantly now. The packaging was simple, nothing fancy, but the hoodie itself feels more expensive than the price suggests. Sleeve length is generous, he had to roll them once or twice.','2026-02-14T08:21:09Z'),
    ('demo-review-1-006@shopupu.local','Lukas Weber',1,5,'I layer this over a tee before gym sessions and it breathes better than I expected for a cotton hoodie. Grey color matches the site photos closely, maybe a touch lighter in person. Stretches fine across the shoulders when I move, no restriction at all.','2026-02-19T07:55:14Z'),
    ('demo-review-1-007@shopupu.local','Anna_W',1,2,'The fleece inside sheds little fibers everywhere after the first wash, found them stuck to a dark shirt I washed with it by accident. Sizing is also inconsistent with their chart, ordered M and it fits more like a regular L. Might return it.','2026-02-27T15:40:37Z'),
    ('demo-review-1-008@shopupu.local','Ingrid H.',1,5,'Wasn''t sure about ordering a hoodie online without trying it first but this turned out great. The black shade is deep, not washed out. Goes with basically anything, jeans, joggers, doesn''t matter. One small thing, the drawstrings are a little short to tie a proper bow.','2026-03-05T12:18:47Z'),
    ('demo-review-1-009@shopupu.local','Piotr Nowak',1,3,'Comfortable fabric, but the sleeves are noticeably too long on me even in M, I have to push them up constantly when I''m actually trying to do anything with my hands. Color is accurate to the photos at least, a proper charcoal grey rather than the washed-out tone some cheaper hoodies end up looking like after a wash or two. The body length is fine, sits right around the hip, and the drawstring holes are reinforced so they''re not fraying yet after several weeks. I think the issue is specifically the sleeve pattern rather than the overall size, because the shoulders and chest fit as expected. Would maybe try a size down next time if that''s even an option, or just accept the rolled-cuff look as part of wearing this one.','2026-03-11T19:26:12Z'),
    ('demo-review-1-010@shopupu.local','kate.mm',1,5,'Simple review, does what it says.','2026-03-17T10:09:03Z'),
    ('demo-review-1-011@shopupu.local','Bettina R.',1,4,'This is my second hoodie from this store and it feels consistent with the first one I bought last year, same weight of fabric and same stitching quality on the cuffs. Grey pairs well with darker pants. It arrived two days later than the estimate but otherwise no complaints.','2026-03-24T16:44:29Z'),
    ('demo-review-1-012@shopupu.local','Sofia Marchetti',1,5,'I was a bit worried the sizing would be strange for my body type but honestly it drapes well and doesn''t look boxy in a bad way. The inside is fleecy without feeling stiff. Would say wash cold since I noticed slight softness loss after the first hot wash cycle.','2026-04-02T13:07:51Z'),
    ('demo-review-1-013@shopupu.local','hannah.vk',1,1,'I am usually a solid M in most brands and this one drowned me, looked more like an XL on my shoulders and the sleeves hung past my hands completely. Fabric itself is decent quality but the fit ruined it for me. Had to send it back for a refund.','2026-04-15T21:12:38Z'),
    ('demo-review-1-014@shopupu.local','Yulia Petrenko',1,4,'This hoodie is nice, is warm and the cotton feels good on skin, not itchy at all even for whole day at home. Delivery box was a little wrinkled but item inside was fine. I think color grey is little more light than picture but still nice.','2026-05-03T06:38:19Z'),
    ('demo-review-1-015@shopupu.local','MaxR_official',1,5,'honestly did not expect much from a generic cotton hoodie but this one surprised me, fabric has real weight to it and the black doesn''t look faded or cheap under bright light 🙂 wore it hiking last month over a base layer and it held up fine against some light drizzle, kept me warm without getting that damp clingy feeling cheaper cotton blends get. the cuffs have stayed tight too, no stretching out after being balled up in a backpack for hours. sized up to L on purpose since I wanted room to layer, and it works exactly like that, roomy through the shoulders but not sloppy. only gripe is the hood bunches up a bit under a backpack strap and the front pocket is a little shallow for holding a phone securely while walking.','2026-05-19T17:55:02Z'),
    ('demo-review-1-016@shopupu.local','Robert Zieliński',1,5,'Went with grey, M. Cut is a bit closer to my body than I expected from an oversized listing, still comfortable though and the stitching around the pocket looks clean. Good for the price honestly, would order the L next time if I want the baggier look.','2026-06-08T22:29:44Z'),
    ('demo-review-2-001@shopupu.local','Nadia Kowalczyk',2,5,'Navy is deeper than I expected from the thumbnail, looks almost like a workwear jacket when zipped up. Zipper glides smoothly, no snagging so far after a few weeks of daily use. Only note is the sleeves sit slightly long past my wrist bone.','2026-01-16T08:40:11Z'),
    ('demo-review-2-002@shopupu.local','Felix Brandt',2,4,'Wear this over a button-down for the office on casual Fridays and it looks put together rather than sloppy. Fabric has decent weight without being bulky under a coat. Hood folds down flat instead of bunching, which I appreciate.','2026-01-23T14:12:37Z'),
    ('demo-review-2-003@shopupu.local','d.kravets',2,5,'no complaints, does the job','2026-02-01T19:03:52Z'),
    ('demo-review-2-004@shopupu.local','Milan Vávra',2,3,'It''s an okay zip hoodie. The fleece sheds a little bit after the first wash, had to lint roll a black jacket that touched it in the dryer. Fit is true to size at least, and the price was reasonable for what you get.','2026-02-08T10:27:44Z'),
    ('demo-review-2-005@shopupu.local','Erik Lindqvist',2,5,'I expected the zipper to feel flimsy for this price range but it''s actually got some heft, metal pull tab and everything, and it hasn''t caught on the fabric once in about two months of near-daily use. Bought it for gym sessions since I need something to throw on before and after lifting, breathes fine and doesn''t trap heat too much even when I forget to take it off between sets. The cuffs stay snug without digging in, and the front pocket is deep enough to actually hold my keys and phone at the same time without them falling out mid-workout. Navy color held up through several washes without fading, still looks the same shade as the day it arrived. Fit through the shoulders is generous enough to move freely but it doesn''t look baggy standing still, which is the balance I was hoping for.','2026-02-16T07:18:29Z'),
    ('demo-review-2-006@shopupu.local','Renata S.',2,4,'Bought this as a gift for my dad and he wears it around the house now most weekends. Runs a bit generous through the body so if he''s between sizes I''d say true to size still works but it drapes looser than a fitted hoodie would. Delivery took a little longer than the estimate, about four extra days.','2026-02-25T20:45:16Z'),
    ('demo-review-2-007@shopupu.local','tobias_k',2,1,'The zipper got stuck halfway up within the second week and I had to work it loose with pliers, not something you want happening on a hoodie you paid full price for. It happened twice more after that, always around the same spot near the chest, so at this point I''ve basically stopped zipping it all the way and just leave it partway open, which defeats the purpose of buying a zip-up in the first place. Fabric feels fine otherwise, decent thickness, no shedding or bobbling that I''ve noticed, and the navy is a nice shade that hasn''t faded despite a few washes. Stitching around the pockets and hem looks tidy too, so it''s really just the one component letting the whole thing down. But a broken zipper on outerwear like this is a dealbreaker for me since it''s the main functional part of the design. Requested a replacement through customer service and I''m waiting to hear back on that.','2026-03-06T12:52:03Z'),
    ('demo-review-2-008@shopupu.local','Ivanna Kravchenko',2,5,'This is nice zip hoodie, material is thick and warm for autumn weather. I order L size because I always order bit bigger and it fit true to size actually so maybe next time I try normal size. Color navy looks exactly like photo, very happy with this purchase.','2026-03-15T09:31:48Z'),
    ('demo-review-2-009@shopupu.local','Claudia Fischer',2,4,'Second one I''ve bought in this cut, first was a different color a while back. Same construction, same stitching along the zip line, consistent with what I remember. A little pricier than I''d like at full cost but worth it on a discount.','2026-03-28T15:09:22Z'),
    ('demo-review-2-010@shopupu.local','sam.oduya',2,5,'Comfortable and warm, wear it constantly now.','2026-04-19T11:24:07Z'),
    ('demo-review-2-011@shopupu.local','Wiktor Adamski',2,3,'The cut is roomier than I anticipated, closer to a slightly large fit even though I ordered my normal size. Zipper and pockets are solid, no issues there. Would probably work better for someone wanting a looser, layered look rather than a snug fit.','2026-05-06T18:16:55Z'),
    ('demo-review-2-012@shopupu.local','leah_wears',2,5,'wasn''t expecting to love a zip hoodie this much lol but the navy is such an easy color to throw on with literally anything, jeans, joggers, doesn''t matter 😊 the inside fleece is soft without being itchy and it hasn''t pilled at all after like six washes. only small thing is the drawcords could be a touch longer','2026-05-21T16:38:40Z'),
    ('demo-review-2-013@shopupu.local','Grzegorz Wójcik',2,4,'Bought this for my son who''s at university, needed something he wouldn''t have to fuss over in terms of washing and care, and it''s held up through the semester without shrinking or losing shape. Sleeves seemed a touch long on him at first but he''s grown into it. Good value overall.','2026-06-30T13:57:29Z'),
    ('demo-review-3-001@shopupu.local','Greta Lindholm',3,5,'The organic cotton fleece is noticeably denser than a standard hoodie, you can feel it the moment you pick it up. Alpine Green is a muted, almost sage tone in person rather than bright, matches the site photos well. Ordered S and the shoulders sit exactly where they should.','2026-01-17T09:22:36Z'),
    ('demo-review-3-002@shopupu.local','Camille Rousseau',3,4,'Pairs really well with cream or off-white bottoms, the green reads as more of a neutral than I thought it would. Silhouette is flattering, not boxy at all for a pullover. Sleeves run a hair long but I don''t mind pushing them up.','2026-01-25T17:05:14Z'),
    ('demo-review-3-003@shopupu.local','j.marek',3,5,'Comfy and warm, would buy again.','2026-02-03T21:14:50Z'),
    ('demo-review-3-004@shopupu.local','Henrik Johansson',3,3,'The fabric is genuinely nice, soft without being flimsy, but the hood itself feels heavy when it''s resting on my back and pulls the collar down a bit. Fit is true to size in M. Would still consider it decent for the price point.','2026-02-11T12:48:27Z'),
    ('demo-review-3-005@shopupu.local','Bianca Toma',3,5,'I wear this under a denim jacket on cooler mornings and it''s just the right thickness, not too warm indoors but enough insulation for the walk to work. The green shade is subtle, works with almost every color I own already. Only small thing, one of the drawstring tips was slightly frayed out of the box.','2026-02-20T08:33:59Z'),
    ('demo-review-3-006@shopupu.local','Nora Eriksen',3,4,'This organic cotton actually feels different from regular cotton hoodies I''ve owned, softer texture and it didn''t stretch out of shape after washing. Sleeves are on the longer side though, had to fold the cuffs twice. Green color is lovely, very earthy.','2026-03-01T15:57:41Z'),
    ('demo-review-3-007@shopupu.local','carla_v',3,1,'I ordered M based on the size chart and it fits like an L on my frame, shoulders drooping well past where they should sit and the whole body just hangs without any real shape to it. I measured myself against the chart twice before ordering, chest and length both lined up with the M column, so I''m not sure where the discrepancy is coming from unless this batch was cut differently. Fabric quality itself seems fine, the fleece is soft and the green colorway looks accurate to the listing, so it''s not a materials complaint. But I can''t wear something this oversized comfortably day to day, it just looks like I grabbed the wrong size off a rack. Ended up returning it for a refund through their exchange process, which was straightforward at least. Wish the sizing was more accurate or that they included real chest measurements per size instead of just S/M/L labels.','2026-03-10T19:22:18Z'),
    ('demo-review-3-008@shopupu.local','wren.styled',3,5,'this hoodie punches well above its price tag honestly, the fleece inside is thick without weighing you down and it hasn''t pilled after a month of regular wear 🌿 alpine green photographs beautifully too, my outfit posts have been getting way more attention lately. sleeves are a touch long but that''s basically the only nitpick','2026-03-22T14:06:33Z'),
    ('demo-review-3-009@shopupu.local','Ewelina Sokolova',3,4,'This hoodie is really soft and warm, I like very much the color, is nice dark green not too bright. I order M size like usual and it fit good, maybe just little loose on the hips but not problem. Only thing is fleece leave small fibers on my black jeans first time.','2026-04-04T10:41:57Z'),
    ('demo-review-3-010@shopupu.local','Aurelia Dumitrescu',3,5,'Usually a M in most brands but this one fits snugger through the chest, glad I read other reviews and sized up. Once I got the L it was perfect, roomy enough to layer a shirt underneath without feeling tight. Stitching on the pouch pocket looks well done, no loose threads.','2026-04-16T18:12:04Z'),
    ('demo-review-3-011@shopupu.local','Matthias Vogel',3,3,'Fabric is solid but I noticed it lost a bit of that initial softness after the first wash on a warm cycle. Fit itself is true to size in S. Not bad, just not as impressive the second time I put it on.','2026-05-02T07:29:11Z'),
    ('demo-review-3-012@shopupu.local','ola.b',3,5,'Warm, soft, good green shade.','2026-05-14T13:50:39Z'),
    ('demo-review-3-013@shopupu.local','Simone Larsen',3,4,'Bought this as a birthday gift for my sister who''s picky about fabric feel and she was happy with the softness right away. Packaging was basic, just a poly mailer, nothing damaged though. She wears S normally and it fit her well from what she told me.','2026-06-05T20:44:26Z'),
    ('demo-review-3-014@shopupu.local','Dorota Lis',3,5,'I''ve bought a couple hoodies from this store before and this one holds up to the same standard I remember, dense fleece, tidy seams along the shoulders, nothing coming loose after regular wear. The Alpine Green is a genuinely nice, wearable shade that doesn''t scream for attention, it reads almost like a muted olive depending on the light, and it hasn''t faded or gone patchy after a handful of washes on a normal cold cycle. Fit in L is roomy without being sloppy, there''s enough room to layer a thermal underneath for colder days but it doesn''t look like I''m wearing a tent. The drawcords and pocket stitching are consistent with the last one I bought too, so whatever they''re doing on the production side seems reliable batch to batch. A bit expensive at full price, but I caught it on a small discount and felt it was worth it then, and honestly I''d probably still buy it again even without one.','2026-06-19T11:17:52Z'),
    ('demo-review-3-015@shopupu.local','Jonas Petersen',3,4,'I wear this to and from the gym over a tank top, breathes reasonably well and doesn''t feel heavy once you warm up. Order came a couple days later than the estimate but nothing major. Fit is true to size in M, sleeves have just enough stretch when I reach overhead.','2026-07-06T16:33:08Z'),
    ('demo-review-4-001@shopupu.local','Marek T.',4,5,'Picked this up for a trip to Lisbon and wore it three days straight without regretting it. The washed linen has that slightly crinkled look already baked in, so nobody could tell I''d slept in a hotel room without an iron. Camp collar sits nicely open, not floppy. Ordered M at 5''11 175 lbs and the length is spot on, hits right at the hip.','2026-02-11T09:14:22Z'),
    ('demo-review-4-002@shopupu.local','Sofie H.',4,4,'Fabric feels great against skin, real linen texture and not scratchy at all. Only complaint is it creases if you so much as look at it wrong, so by hour four at my desk the front looked like I''d wrestled someone. Still buying another one in a different color.','2026-01-22T18:41:07Z'),
    ('demo-review-4-003@shopupu.local','dkowalczyk',4,5,'Comfortable, breathable, ivory is a true off-white.','2026-03-03T07:55:41Z'),
    ('demo-review-4-004@shopupu.local','Bianca R.',4,3,'It is an okay shirt. The linen is thinner than I expected for the price, almost see-through under strong light. Sizing worked out true to size in M. I will probably still wear it around the house but not somewhere I need to look sharp all day.','2026-04-09T13:27:55Z'),
    ('demo-review-4-005@shopupu.local','Renata O.',4,5,'He''s not usually picky about clothes but he texted me a photo of himself wearing it at the lake house so I''m calling that a win. Went with L based on his usual size and it fit him without any adjustment needed, no last-minute exchange required which is always a relief with gifts. The collar structure holds up even after he tossed it in a bag for the drive, didn''t come out looking crushed the way some travel shirts do. Wrapping was simple, just tissue paper and a box, but for the price that''s expected and it didn''t detract from the gift. He mentioned the fabric felt cooler than the cotton shirts he usually wears, which matters since he runs warm most of the year. Already planning to get him the same style in a darker color for his birthday next time.','2026-05-14T20:03:12Z'),
    ('demo-review-4-006@shopupu.local','Tobias L.',4,4,'Really like the weight of this fabric for summer. The short sleeves on my S actually hit a bit lower on my arm than I pictured, more mid-bicep than I''d call short-short, but it''s not a dealbreaker. Pairs well with linen shorts or rolled chinos.','2026-02-28T11:38:49Z'),
    ('demo-review-4-007@shopupu.local','Iga Nowak',4,5,'I was ready to be disappointed after a couple of bad linen buys elsewhere but this held up. Washed it cold, hung it dry, no shrinkage, and the ivory kept its tone instead of going yellowish like cheaper linen sometimes does. M fits close to how the size chart described.','2026-06-01T16:52:30Z'),
    ('demo-review-4-008@shopupu.local','Callum B.',4,5,'Wore this every single day of a five day trip and it earned its spot in the suitcase. Camp collar, breathable weave, easy to dress up with linen trousers or down with swim trunks. Ordered a size up to L for a relaxed fit and that was the right call for me, I like shirts a bit loose in this style.','2026-03-19T08:07:16Z'),
    ('demo-review-4-009@shopupu.local','Henrik A.',4,2,'The camp collar looked structured in the product photos but on mine it''s floppy and doesn''t hold shape even after ironing. Fabric itself is nice enough, soft and cool for summer, but the collar issue is what I actually see every time I put it on so it bothers me more than it probably should.','2026-04-25T19:44:03Z'),
    ('demo-review-4-010@shopupu.local','Priya M.',4,4,'Comfortable all day, moves with you, doesn''t stick to your back on a hot commute. Color is a bit darker than in the photos, more of a light oatmeal than pure ivory on my screen, but I actually prefer it in person. True to size in S for my frame.','2026-05-30T10:19:44Z'),
    ('demo-review-4-011@shopupu.local','yusuf_k',4,5,'for the price point i was not expecting real linen feel, more like a linen-cotton blend look, but the tag confirm it is linen. wearing it now three week already and washed two time, still keep shape good. i buy size M same like other shirt i have and is correct fit for me. only small thing, need iron after wash or looks little crumpled.','2026-06-18T21:26:58Z'),
    ('demo-review-4-012@shopupu.local','Gustaf E.',4,3,'Ordered my usual M and the shoulder seams sit slightly narrow, noticeable when I raise my arms. Fabric quality is decent, the ivory shade matches the listing photos well. Might exchange for L, undecided yet since everything else about it works fine.','2026-01-30T15:12:39Z'),
    ('demo-review-4-013@shopupu.local','Adelina V.',4,5,'Already own the navy and sage version from a previous season so I know what I''m getting with these camp shirts, and the ivory doesn''t disappoint. Consistent sizing across all three, all in L, same relaxed but not baggy cut through the body. Stitching on the button placket looks cleaner than my older one too, might be a small quality bump this run. Worth it if you already like the fit.','2026-06-27T12:48:05Z'),
    ('demo-review-4-014@shopupu.local','Nadia S.',4,1,'Shirt arrived with a small snag near the hem and the fabric feels much thinner than I hoped, almost papery when held up to light. I sized down to S thinking it might run large based on other reviews but it''s true to size so now it''s just loose and thin at once. Returning it. Delivery itself was fast at least, arrived two days early.','2026-03-08T06:33:27Z'),
    ('demo-review-5-001@shopupu.local','Camila R.',5,5,'This has become my go-to under blazers and open flannels. Ribbed knit holds its shape without feeling like a compression top, and the black is a true deep black even after five washes. I''m usually a M in fitted tops and M here matches that exactly.','2026-01-19T14:02:11Z'),
    ('demo-review-5-002@shopupu.local','Elin S.',5,4,'It''s a close, ribbed fit so don''t expect any room to spare, especially through the chest. I got S which is my normal size and it hugs more than I anticipated but that''s on me for not reading close enough. Fabric itself is nice and thick for a tank, not see through at all.','2026-02-06T09:47:38Z'),
    ('demo-review-5-003@shopupu.local','vega.k',5,5,'Simple, fitted, holds shape after washing.','2026-03-14T18:29:55Z'),
    ('demo-review-5-004@shopupu.local','Halina D.',5,3,'Went with my usual M but this ribbed style runs closer to the body than a standard tank, so it reads more like a base layer than something I''d wear alone. Fabric quality is fine and the stitching at the straps is clean. Might size up next time or just wear it under something open.','2026-04-02T21:15:07Z'),
    ('demo-review-5-005@shopupu.local','Josie P.',5,5,'Wear this to pilates then straight to the grocery store without changing, it''s stretchy enough to move in but not so thin it goes sheer when you sweat. Got L for a bit of extra room since I layer sports bras under it. Ribbing hasn''t loosened up or lost shape after regular wear.','2026-05-11T07:33:20Z'),
    ('demo-review-5-006@shopupu.local','Tamsin O.',5,4,'Great everyday tank for the price. If you''re between sizes I''d size up, the bust area is snugger than the rest of the body on my S. Color hasn''t faded after washing in cold water, which surprised me a little for black fabric.','2026-01-27T11:58:44Z'),
    ('demo-review-5-007@shopupu.local','brookenm',5,5,'college budget doesn''t leave much room for mistakes but this one was worth it, wore it literally every week since it arrived. soft ribbed cotton, not scratchy, and it actually held up in the dorm washer which honestly shocked me since most of my cheap stuff gets wrecked by like the third wash. got M and it''s snug in a good way not a squeezed way, works fine layered under a flannel for class or on its own when it''s warmer out. the straps don''t dig into my shoulders either which is something i actually notice after a full day of wearing a backpack. only small thing is it picked up a little bit of pilling near where the backpack strap sits, not terrible but visible up close. still bought two more in different colors right after because for the price i really can''t complain.','2026-06-05T22:41:16Z'),
    ('demo-review-5-008@shopupu.local','Noor A.',5,5,'The black is genuinely black, not the faded charcoal you sometimes get online. Ribbing gives it a bit of shape without being tight everywhere, more fitted through the waist than the chest which I like. XS fits my frame well, true to my usual size in this brand.','2026-02-20T16:04:29Z'),
    ('demo-review-5-009@shopupu.local','Ragnhild K.',5,1,'Followed the care label exactly, cold wash, laid flat to dry, and it still came out noticeably shorter than when it arrived. Now it barely reaches my waist and rides up constantly. Fabric feel was actually nice before the wash so I''m annoyed this happened. Wouldn''t buy again unless this gets fixed.','2026-03-24T13:22:51Z'),
    ('demo-review-5-010@shopupu.local','Delphine M.',5,4,'Easy to style with jeans or under a cardigan, works as a real basic. The strap width sits comfortably on my shoulders, doesn''t dig in during a long day. Small complaint is it wrinkles a bit if left balled up in a drawer but a quick shake usually sorts that out.','2026-04-17T08:16:03Z'),
    ('demo-review-5-011@shopupu.local','Wren T.',5,5,'Bought this for layering under my work shirts and it''s perfect, doesn''t bunch up or show lines. L runs true and the ribbed texture actually looks intentional rather than just being a plain tank. Already thinking about grabbing a second one as backup.','2026-05-23T19:39:47Z'),
    ('demo-review-5-012@shopupu.local','Ottilie F.',5,3,'Does the job as a basic layering tank, nothing special about it either way. Ribbing is a little looser than I expected for the fitted look shown in photos, more relaxed on me in M. Delivery took a little longer than the estimate but arrived undamaged.','2026-06-12T10:51:34Z'),
    ('demo-review-5-013@shopupu.local','elif.aydin',5,5,'already have this tank in white from last year and buy black now because first one still look almost new after so many wash. rib knit keep shape very well, not stretch out at neckline like cheap tank do. size S same both time, fitting is correct for me, close to body but comfortable still.','2026-02-14T15:47:02Z'),
    ('demo-review-5-014@shopupu.local','Björn L.',5,4,'Soft, fits close, good under jackets.','2026-07-01T12:09:18Z'),
    ('demo-review-5-015@shopupu.local','Petra V.',5,5,'I almost skipped this because tank tops at this price point are usually thin and lose shape fast, but the ribbing here has real structure. Wore it under a denim jacket for a weekend trip and it held its own as a standalone top too. Ordered XS since I run small in most brands and it''s snug through the torso without feeling restrictive, exactly the fit I was after. Color stayed rich black through two washes so far, no fading visible yet.','2026-03-30T20:58:12Z'),
    ('demo-review-6-001@shopupu.local','Marta Kowalska',6,5,'I''ve bought merino sweaters before that felt scratchy against the neck, but this one doesn''t. Ordered a Medium and it sits close without being tight anywhere. Washed it once on wool cycle and it came out the same shape it went in.','2026-01-19T08:14:22Z'),
    ('demo-review-6-002@shopupu.local','Daniel R.',6,5,'Works well under a jacket or on its own with jeans. The heather gray is more of a mid-tone than I expected, reads a little lighter in person than the product photo.','2026-02-03T19:41:07Z'),
    ('demo-review-6-003@shopupu.local','sof.ia_wears',6,4,'The material feel is very nice, not too heavy for indoor wear also. Maybe I wait for discount to buy second one because full price is a bit much for student budget like mine.','2026-01-27T12:05:44Z'),
    ('demo-review-6-004@shopupu.local','Helena Bakker',6,5,'Wear this over a collared shirt most days now. Holds its shape after a full day at the desk and doesn''t pill where the bag strap sits, which surprised me.','2026-02-14T09:22:31Z'),
    ('demo-review-6-005@shopupu.local','Nikos P.',6,4,'Got the L for my brother''s birthday since he runs a bit broad in the shoulders. He says it''s the softest sweater he owns now. Only downside is the box arrived a little crushed, sweater itself was fine.','2026-02-21T16:38:12Z'),
    ('demo-review-6-006@shopupu.local','Priya Nair',6,3,'It''s a decent sweater and true merino feel, but I expected something with more weight to it for the price. Wears more like a spring layer than a winter one. Not bad, just not what I had in mind.','2026-03-02T21:07:55Z'),
    ('demo-review-6-007@shopupu.local','T. Reyes',6,5,'Solid everyday sweater.','2026-03-11T07:52:03Z'),
    ('demo-review-6-008@shopupu.local','Andrei Voicu',6,4,'I sized down to S from my usual and it''s still slightly roomy through the body, sleeves are a good length though. Fabric feels dense and warm, no complaints there. Would recommend checking the size chart twice before ordering.','2026-03-19T14:29:40Z'),
    ('demo-review-6-009@shopupu.local','Owen Fitzgerald',6,5,'Was expecting it to be itchy like other wool sweaters I''ve owned. Pleasantly surprised, it''s soft against skin and I can wear it with just a t-shirt underneath. Sleeves hit right at the wrist for me at 5''11".','2026-04-02T18:16:29Z'),
    ('demo-review-6-010@shopupu.local','kb_thrift',6,3,'its fine..little bit of pilling under the arms after two washes, nothing crazy but i noticed it right away. color''s accurate to the listing at least so thats something','2026-04-15T10:44:18Z'),
    ('demo-review-6-011@shopupu.local','Jamal Whitfield',6,4,'I throw this on after workouts before heading out and it doesn''t trap heat the way my old acrylic one did. Breathes decently for a knit. One small thing, the ribbing at the collar loosened up slightly after a month of regular wear.','2026-04-27T20:03:51Z'),
    ('demo-review-6-012@shopupu.local','Elin Sundqvist',6,5,'Bought the same sweater in a different color last year and it held up so well I came back for gray. Consistent sizing between the two, both washed the same and neither shrank, which is honestly rare for me since I''ve had wool pieces from other places stretch out or go bobbly within a couple of months. Genuinely one of the better basics I own at this point, and the stitching at the shoulder seams still looks new even after regular rotation through the colder months. I''ve worn it under a coat for commuting and on its own around the house, and it holds its shape either way. If the price drops around the holidays I''ll probably grab a third color, since at this point I trust the sizing enough to not think twice about it.','2026-05-09T11:27:14Z'),
    ('demo-review-6-013@shopupu.local','Carla Mendes',6,1,'Ordered my normal size M and it''s noticeably too small across the chest, had to size up and return it. On top of that it pilled badly around the cuffs within the first week of wearing it, which I did not expect from merino at this price point. Might try again in a size L but not confident after this.','2026-05-24T15:58:37Z'),
    ('demo-review-6-014@shopupu.local','yuki.style',6,5,'The gray is exactly like the photos, maybe even nicer in person. Soft enough to skip a base layer and it moves with me fine, no restriction across the shoulders when I reach up.','2026-06-30T13:11:59Z'),
    ('demo-review-7-001@shopupu.local','Marieke V.',7,5,'Ordered the S and it landed exactly like the model photos, cropped right above the waistband. Only gripe is the top button is a little stiff to close one-handed.','2026-01-19T09:14:22Z'),
    ('demo-review-7-002@shopupu.local','Colin B.',7,4,'The medium blue wash is close to the site photos, maybe a shade lighter in daylight. Sleeves run slightly long on me and I''m not petite, so I''ve been rolling the cuffs. Otherwise a solid jacket for the price and it pairs well with almost everything in my closet.','2026-01-24T18:02:10Z'),
    ('demo-review-7-003@shopupu.local','avaonrepeat',7,5,'Denim feels sturdy, not stiff. Sized down to XS for a snug fit through the shoulders and it worked out great.','2026-02-02T13:45:51Z'),
    ('demo-review-7-004@shopupu.local','Renske',7,3,'It''s fine. Fits true to size in the M, crop length is shorter than I pictured, sits well above my belly button. Not much else to say.','2026-02-08T11:30:00Z'),
    ('demo-review-7-005@shopupu.local','Jules T.',7,5,'Solid staple.','2026-02-14T20:11:05Z'),
    ('demo-review-7-006@shopupu.local','Bo Hendrickx',7,4,'Bought this for weekend errands and it''s been great over hoodies and tank tops both. There was one loose thread near the hem when it arrived, snipped it off and no issue since. The stitching elsewhere looks clean and the pockets are a nice functional touch.','2026-02-21T08:55:40Z'),
    ('demo-review-7-007@shopupu.local','Priya N.',7,5,'I was ready to be a little disappointed given the price point but this actually feels more expensive than it is. The wash is a nice medium blue, not too light or too dark, and the buttons feel secure. Got the L for an oversized look on purpose and it delivers exactly that.','2026-02-27T16:20:33Z'),
    ('demo-review-7-008@shopupu.local','Fenna',7,4,'The cut through the body is roomy but I noticed some pull across the shoulders in my usual size, M. Went with the L instead, better now. Would still buy again.','2026-03-03T07:40:12Z'),
    ('demo-review-7-009@shopupu.local','sophieanne_',7,5,'Hits right at the waist, no fading after washing.','2026-03-10T19:05:18Z'),
    ('demo-review-7-010@shopupu.local','K. Verbeek',7,1,'Disappointed with this one honestly. The photos show a light-medium wash but what arrived looks almost like a dark indigo, nothing like the listing. Fit is okay in the M but I mostly bought it for that specific color and it just isn''t it. Considering returning.','2026-03-16T12:48:27Z'),
    ('demo-review-7-011@shopupu.local','Anneke D.',7,5,'I already own two other jackets from here and this one keeps the same quality I''ve come to expect. Consistent sizing too, ordered my usual S and it matched perfectly.','2026-03-24T14:10:55Z'),
    ('demo-review-7-012@shopupu.local','Thomas R.',7,4,'Got this for my sister''s birthday since she''d been eyeing something similar. Went with M based on her usual size but it''s noticeably roomy on her, swimming a bit in the shoulders and sleeves, probably should have gone S. She still likes it and says the denim feels sturdier than jackets twice the price, so overall a win despite the sizing miss. Packaging was simple but the jacket itself arrived in perfect condition.','2026-04-02T10:33:41Z'),
    ('demo-review-7-013@shopupu.local','Els Peeters',7,5,'For a cropped style I was worried it''d feel like a costume piece but it''s genuinely wearable denim. Good weight, moves fine when I''m walking around, doesn''t restrict my arms reaching for things on shelves at work. Sized up to M from my usual S for a bit more ease and glad I did.','2026-04-15T21:26:09Z'),
    ('demo-review-7-014@shopupu.local','nora.k',7,3,'It is what it is for the price. XS fits close to true to size, denim wrinkles more than I''d like. Not sending it back, just not blown away.','2026-04-29T06:52:14Z'),
    ('demo-review-7-015@shopupu.local','Isabelle M.',7,5,'I throw this on over leggings after the gym and it still looks put together instead of like I''m still mid-workout. Has enough give across the back for reaching and stretching, which genuinely surprised me for a denim jacket, most rigid fabrics fight you the second you lift your arms overhead. Grabbed the S, true to size through the shoulders and torso, and it''s held up through weekly washes with zero shrinkage so far, still the same length and cut as day one. The pockets are deep enough to actually hold my phone during a walk, which sounds minor but matters more than I expected. Would order the same style in another wash if they add one 🙂','2026-05-20T17:38:02Z'),
    ('demo-review-7-016@shopupu.local','Dimitri',7,4,'Jacket itself is nice, fits true to size in L, decent weight to the denim. My only complaint is delivery took about four extra days.','2026-06-11T15:47:29Z'),
    ('demo-review-8-001@shopupu.local','Grant O.',8,5,'Wear this over a dress shirt three or four times a week and it still looks pressed by end of day. Charcoal is a true neutral, not blue-toned. M fit close through the chest and shoulders, exactly what I wanted.','2026-01-17T08:20:11Z'),
    ('demo-review-8-002@shopupu.local','Marcus D.',8,4,'Wool blend feels dense and holds a crease well. Shoulders sit tighter than I''d like in my usual L, noticeable when I reach forward at a desk. Might size up to XL next time.','2026-01-25T19:44:02Z'),
    ('demo-review-8-003@shopupu.local','R. Callens',8,5,'Not too heavy, not flimsy either.','2026-02-01T14:12:39Z'),
    ('demo-review-8-004@shopupu.local','Youssef B.',8,3,'I have somewhat broad shoulders and even sizing up to XL there''s still a bit of pull across the back when my arms are forward. Fabric itself is nice quality. Just wish the shoulder seam had more room.','2026-02-09T11:05:47Z'),
    ('demo-review-8-005@shopupu.local','Wouter',8,5,'I went in with low expectations honestly, blazers at this price point are usually hit or miss, either the fabric feels like cardboard or the shape falls apart after a few wears. This one surprised me on both counts. The charcoal shade matches the site photos closely, maybe a hair lighter in direct sun but nothing you''d notice indoors. Ordered M, true to size through the torso and waist, and the lining inside feels smooth rather than scratchy against a dress shirt, which matters when you''re wearing it eight hours straight at a desk. The two-button front sits flat instead of pulling, and after wearing it to three separate meetings now it still holds its shape with no visible creasing at the elbows. For the price I was fully prepared to be let down and instead I''m considering a second one in navy if they make it.','2026-02-18T09:30:15Z'),
    ('demo-review-8-006@shopupu.local','jaydenlooks',8,4,'cant complain much, fits fine in S and the wool blend actually feels like wool not that cheap synthetic stuff. sleeves ran maybe half an inch long but nothing a tailor cant fix in five minutes. good for job interviews imo','2026-03-01T22:18:53Z'),
    ('demo-review-8-007@shopupu.local','Céline Ferrand',8,5,'Picked the L based on his usual jacket size and it fit him right out of the box, no exchange needed. He says the wool feels warmer than his old blazer without feeling bulky.','2026-03-14T16:41:20Z'),
    ('demo-review-8-008@shopupu.local','Henrik S.',8,1,'Ordered my normal size M based on the chart and could barely close the top button without the fabric pulling across my back. Fabric feels decent but a blazer that fights you when you move your arms is not usable for actual office wear. Had to send it back for a refund.','2026-03-27T13:09:44Z'),
    ('demo-review-8-009@shopupu.local','Peter Aerts',8,4,'Same quality as my last order. XL fit matched perfectly again.','2026-04-10T10:52:36Z'),
    ('demo-review-8-010@shopupu.local','Simon L.',8,5,'This is my go-to now for anything semi-formal. Two-button front sits nicely, the wool blend has a slight texture to it rather than looking flat and cheap. Went with my usual M and it''s true to size everywhere except the sleeves, which land just slightly long, easy fix if you care about that kind of thing.','2026-05-02T20:15:07Z'),
    ('demo-review-8-011@shopupu.local','Anke',8,3,'Wanted to like this more than I do. Shoulders sit a little tight in L and the shape feels boxier than the photos suggested. Not returning it, just not the sharp cut I expected.','2026-05-19T07:33:58Z'),
    ('demo-review-8-012@shopupu.local','N. Vanderhoeven',8,5,'Checked the inside seams before buying and these look reinforced properly, no loose threads anywhere. S fits true to size, maybe a touch roomy in the waist, which I actually prefer.','2026-06-08T18:27:14Z'),
    ('demo-review-8-013@shopupu.local','Ola Wiśniewski',8,4,'Layer this over a sweater in colder months and it still closes fine without feeling tight, so the cut has some room built in for that. XL true to size on my frame. Only real complaint is it''s a bit much for warmer days, wool blend traps heat more than I expected walking between meetings outside.','2026-06-25T12:44:29Z'),
    ('demo-review-9-001@shopupu.local','Charlotte M.',9,5,'This has quickly become my rain-day go-to. Cotton twill has a nice weight, structured without feeling stiff. Ordered S true to size and the belt cinches nicely at the waist.','2026-01-16T10:05:33Z'),
    ('demo-review-9-002@shopupu.local','Rob T.',9,4,'Good quality twill, not see-through at all. Sleeves land past my wrist bone in the M though, have to fold them back.','2026-01-28T15:22:09Z'),
    ('demo-review-9-003@shopupu.local','hannah.wears',9,5,'Works over both office clothes and jeans.','2026-02-04T13:47:51Z'),
    ('demo-review-9-004@shopupu.local','Maren H.',9,3,'It''s lightweight, which the listing does say, but I was hoping for something I could wear into early winter and this is really more of a spring or light autumn piece. Sizing was also off, ordered my usual L and it''s noticeably baggy through the body and sleeves, could have gone down a size easily. The buttons also feel a little cheap for the price, slightly loose on the top one already.','2026-02-13T08:16:40Z'),
    ('demo-review-9-005@shopupu.local','Delphine A.',9,5,'I own a much pricier trench and reach for this one more often now. Fabric drapes well, not boxy at all. Sized down to XS for a closer fit and it worked out.','2026-02-22T19:38:12Z'),
    ('demo-review-9-006@shopupu.local','livvy_b',9,4,'was worried it''d look cheap in person but its actually pretty nice. beige shade is a little more grey-ish than the photo tbh. M fit true to size, only thing is it wrinkled a bit from being folded in the package','2026-03-05T21:50:27Z'),
    ('demo-review-9-007@shopupu.local','David K.',9,5,'Bought this for my mother''s birthday, went with M based on her other coats and it fit her well, sleeves a touch roomy but nothing bothersome. She''s worn it three times already, a strong sign of approval from her.','2026-03-19T11:29:03Z'),
    ('demo-review-9-008@shopupu.local','Petra L.',9,1,'The listing shows a warm camel-beige and what showed up looks almost grey-taupe in normal light. Really disappointed since color was the whole reason I picked this. Fit is fine in S, but I want to send it back for the shade.','2026-04-01T14:05:58Z'),
    ('demo-review-9-009@shopupu.local','Margaux Renard',9,4,'This is my second trench from this store, construction quality matches the first one from two years ago. Same true-to-size fit in my usual S. Twill feels marginally thinner but still holds shape.','2026-04-16T09:41:15Z'),
    ('demo-review-9-010@shopupu.local','Yuki Tanaka',9,5,'Wear it walking to work most mornings, light enough that it doesn''t feel like carrying extra weight but still blocks wind decently. L fit true to size. One interior seam has a slightly loose thread, purely cosmetic though.','2026-05-06T16:12:44Z'),
    ('demo-review-9-011@shopupu.local','Astrid',9,3,'Nothing wrong with it exactly, fit is true to size in M and the shape looks good on. Fabric wrinkles more than I anticipated though, had to steam it before the first wear. Price felt slightly high for what it is.','2026-05-24T07:58:20Z'),
    ('demo-review-9-012@shopupu.local','Noor El Amrani',9,5,'Wasn''t sure about ordering a coat online without trying it on first but this turned out great. The beige tone is warm and flattering against most of what I already own, not the flat grey-beige that some listings show in photos and then ship something duller. The belt actually stays tied instead of slipping loose every twenty minutes like some I''ve had in the past, small detail but it makes a real difference walking around all day. XS fit snug through the shoulders exactly how I like a trench to sit, structured without feeling restrictive when I''m carrying bags or reaching into a bus door. After one cold wash it held its shape completely, zero shrinkage and the collar still stands the way it did out of the box. The interior lining also doesn''t bunch up under a blazer, which surprised me since that''s usually where cheaper trenches fall apart first. Would happily order the next color they release, and I''ll probably grab a second one before winter just to rotate.','2026-06-02T20:34:51Z'),
    ('demo-review-9-013@shopupu.local','Emiel V.',9,4,'Coat itself is well made, twill has a nice hand-feel and the buttons line up evenly on both sides. Arrived folded in a plastic bag, came a bit wrinkled but a quick steam sorted it out. S fits true to size.','2026-06-19T12:26:37Z'),
    ('demo-review-9-014@shopupu.local','camille_dupre',9,5,'Roomy enough to layer without looking bulky.','2026-07-03T17:15:09Z'),
    ('demo-review-10-001@shopupu.local','Marika Sowa',10,5,'Ordered the M and it sits exactly like the size chart said it would. The quilting is thicker than I expected for the price and it hasn''t lost shape after a month of daily wear over hoodies. Sage is more of a muted olive in person, which I actually prefer.','2026-01-19T08:14:22Z'),
    ('demo-review-10-002@shopupu.local','D. Renner',10,4,'Zipper feels a little cheap, catches sometimes when I pull it up fast. Otherwise solid - warm enough for spring mornings and sage matches the photos.','2026-01-27T19:03:10Z'),
    ('demo-review-10-003@shopupu.local','jules_wanders',10,5,'Runs true to size, comfy over a sweater.','2026-02-02T11:45:00Z'),
    ('demo-review-10-004@shopupu.local','Peter H.',10,3,'The quilting looks good and the stitching is neat, no complaints there. But I live somewhere cold and this is really more of a mild-weather piece than an actual winter vest - I still need a coat underneath once it drops below freezing. Fine for what it is, just don''t expect heavy insulation.','2026-02-08T16:22:47Z'),
    ('demo-review-10-005@shopupu.local','Simona R.',10,5,'Got this as a gift for my brother who''s picky about outerwear and he''s actually worn it every weekend since. The XL gave him room to layer a flannel underneath without looking bulky. Packaging was simple but the vest itself arrived in perfect condition.','2026-02-15T09:37:55Z'),
    ('demo-review-10-006@shopupu.local','Sam T.',10,4,'Wait, it''s sleeveless, oops. Shell fabric feels nicer than expected, sage is a bit darker than the photos. Would size up for a looser fit.','2026-02-21T14:09:31Z'),
    ('demo-review-10-007@shopupu.local','Coach_Ivo',10,5,'Wear this over a tee on cooler gym mornings and it doesn''t restrict arm movement at all since there are no sleeves to worry about. Breathable enough that I don''t overheat walking to the car after a workout. Shoulders sit right at true to size in the M, no bunching.','2026-03-01T07:52:18Z'),
    ('demo-review-10-008@shopupu.local','Owen Bradshaw',10,1,'I ordered my usual L and the shoulder seams sit noticeably tight, almost restrictive when I reach forward. For a quilted vest that shouldn''t happen since there''s no sleeve to account for. Sent it back for a refund, wouldn''t reorder without trying it on first.','2026-03-09T20:11:04Z'),
    ('demo-review-10-009@shopupu.local','hannah.m',10,4,'Simple, warm-ish, goes with almost everything in my closet already. A little snug through the chest in S but nothing uncomfortable, just noted it.','2026-03-16T13:28:40Z'),
    ('demo-review-10-010@shopupu.local','Yulia Marchenko',10,5,'Bought a hoodie from this store last year that held up really well after dozens of washes, so I trusted the brand enough to grab this vest too without overthinking it. Same story here overall - the sage colorway looks accurate against the listing photos, the quilting hasn''t flattened out even after weekly wear since March, and the fit is consistent with their size chart the same way the hoodie was, which is honestly rare across different clothing categories from the same store. Only tiny note is one loose thread near the hem that I noticed after the first wash, I just snipped it off myself with scissors and it hasn''t unraveled any further since. Would buy from them a third time at this point.','2026-03-24T18:47:12Z'),
    ('demo-review-10-011@shopupu.local','T. Bergstrom',10,5,'Honestly expected this to be more of a decorative layer than something functional, but I''ve worn it on a few chilly hikes and it holds heat better than I thought a sleeveless piece could. Zipper pull is a bit small for gloved hands, minor gripe. Sage color reads a touch more grey-green outdoors than in the listing photo.','2026-04-02T10:03:59Z'),
    ('demo-review-10-012@shopupu.local','Radoslav K.',10,2,'The fabric feels thinner than the photos suggest and after washing once the quilting looks slightly flatter in a couple spots. Fit is fine, true to size in the XL, but for the price I expected the material to hold up a bit better right out of the gate.','2026-04-11T15:36:27Z'),
    ('demo-review-10-013@shopupu.local','nadia_k',10,5,'Good vest, comfortable for the price 🙂','2026-04-19T21:58:03Z'),
    ('demo-review-10-014@shopupu.local','Mihaela D.',10,3,'I order size M because usual my size in most stores, but this one come more big than I think, maybe cut is different from normal jacket in my country. Quality of the fabric is nice and stitching look clean, no problem there, this part I am satisfied. Just next time I will order S instead, I think that will fit closer to my body. Color also litle darker than picture but is fine still, not big problem for me since I wanted dark green anyway. My husband also try it on and he say shoulders feel comfortable, better than the jacket he bought before from different website. Overall is good vest, just pay attention to size before you order because chart maybe not so accurate for this item.','2026-05-06T12:14:38Z'),
    ('demo-review-10-015@shopupu.local','kelan.j',10,4,'ordered this like 2 weeks before i actually needed it thank god bc shipping took way longer than the estimate, arrived almost a week late. vest itself tho, no complaints - sage is a good neutral color, fits true to size in L and layers fine over a flannel. just order early lol','2026-06-02T17:41:50Z'),
    ('demo-review-11-001@shopupu.local','Marek Dvorak',11,5,'Picked the 32 based on the size chart and it landed right where I wanted, no gaping at the back waist like some straight legs do. The denim has a bit of heft to it rather than feeling paper thin, and the medium blue wash looks close to the product photos. Only wish the hem came slightly pre-finished since I''ll need to take it up an inch.','2026-01-19T09:14:22Z'),
    ('demo-review-11-002@shopupu.local','Aoife K.',11,4,'Ordered a 34 and it''s comfortable through the thigh without being baggy. First two wears the denim felt stiffer than I expected for a straight leg, softened up after a wash and dry cycle though. Color is a true medium blue, not the faded look some listings show. Would order again.','2026-02-02T18:41:07Z'),
    ('demo-review-11-003@shopupu.local','jenny_thrifts',11,3,'The waist on my 30 was fine, actually sat comfortably, but the inseam is longer than most straight legs I own so I ended up pooling at the ankle unless I cuff them. Fabric quality is decent for the price. Not a bad pair, just wasn''t expecting to need a tailor.','2026-01-27T21:05:44Z'),
    ('demo-review-11-004@shopupu.local','Tomas B.',11,5,'Comfortable, honest medium blue.','2026-02-11T08:02:15Z'),
    ('demo-review-11-005@shopupu.local','DerekM_repeat',11,5,'I''ve bought two other jeans from this store and these are the best cut yet, the straight leg actually stays straight instead of tapering weirdly by the ankle. Sized down to a 34 from my usual 36 in other brands since the waist runs a touch generous. Movement is fine for walking around all day, and the stitching on the back pockets looks clean up close.','2026-02-19T13:37:50Z'),
    ('demo-review-11-006@shopupu.local','Petra Novakova',11,4,'These run a little snug through the waist, I''d size up if you''re between two. Once I exchanged the 34 for a 36 the fit was comfortable for sitting at a desk all day. The blue is exactly the medium wash pictured, not too dark or too washed out.','2026-03-03T16:20:11Z'),
    ('demo-review-11-007@shopupu.local','quietwardrobe',11,5,'True to size, comfortable, would buy in another wash.','2026-03-08T11:55:33Z'),
    ('demo-review-11-008@shopupu.local','Cian Fitzgerald',11,1,'I normally wear a 34 in straight leg cuts and this one fit more like a 32, could barely button it after one gym session where I usually have room to spare. The stretch is minimal compared to what the description implied, so if you''re between sizes go up two, not one. Disappointed since the color and stitching are genuinely nice, just couldn''t keep them.','2026-01-24T20:10:02Z'),
    ('demo-review-11-009@shopupu.local','Silvie H.',11,5,'Wasn''t expecting much from an online jeans purchase but the 32 fit close to how my in-store pairs usually do. Denim has a nice mid-weight feel, not the thin stretch stuff, and after a cold wash it kept its shape with no fading around the knees. My only note is the belt loops are set a bit close together but that''s minor.','2026-03-15T07:44:29Z'),
    ('demo-review-11-010@shopupu.local','Maggie R.',11,4,'Bought a 36 for my dad for his birthday, he wears these constantly now for weekend errands. He mentioned the waistband sits a little looser than his old pair so he might''ve gone with a 34 in hindsight, but he''s not sending them back. Good value for what you pay.','2026-03-22T15:03:47Z'),
    ('demo-review-11-011@shopupu.local','brnoblue',11,5,'Denim on these is thicker than expected, holds a crease nicely.','2026-04-01T12:18:59Z'),
    ('demo-review-11-012@shopupu.local','Cian_walks',11,3,'Waist fits, fabric is thinner than I hoped, and the stretch wears out by evening. Not bad for the price but I probably wouldn''t reorder the same style.','2026-04-09T19:27:14Z'),
    ('demo-review-11-013@shopupu.local','Renata Kovacova',11,5,'I was ready to be let down after a couple bad denim orders elsewhere but this held up fine, the medium blue color matched the listing and the fit through the hip and thigh was true to size in a 32. Length was just slightly long so I rolled the cuff once, which actually looks intentional with sneakers. Would recommend sizing normally here.','2026-04-17T10:33:41Z'),
    ('demo-review-11-014@shopupu.local','leah.wears',11,5,'Comfy for class and part time job shifts, denim not too heavy for standing all day. Waist true to size for me at 30. Will get another color next paycheck.','2026-04-28T22:09:37Z'),
    ('demo-review-11-015@shopupu.local','Barnaby T.',11,2,'The color is noticeably more muted than shown on my screen, closer to a washed grey-blue than the medium blue in the photo. Fit itself was fine at 36, no complaints there, but I bought these specifically for the color and that part missed. Might keep them anyway since the cut is decent.','2026-05-06T14:52:03Z'),
    ('demo-review-11-016@shopupu.local','Imogen Walsh',11,4,'I compare fabric weight and stitching pretty closely before keeping anything and these passed. Seam allowance is even, the rise sits mid, not low, and there''s a light break at the shin in a 34 which I like for a straight leg. One loose thread near the coin pocket but nothing that affects wear.','2026-05-19T08:47:26Z'),
    ('demo-review-11-017@shopupu.local','Nadia Prochazka',11,5,'For this price point I did not expect the denim to feel this substantial, my 32 fits close to designer straight legs I''ve paid three times as much for. Delivery took a bit longer than the estimate but the jeans themselves arrived folded neatly with no creases. Washed once cold and hung to dry, no shrinkage or color bleed. Already thinking about grabbing the black version too.','2026-06-02T17:15:58Z'),
    ('demo-review-12-001@shopupu.local','Klara Svobodova',12,5,'The pleats hold their shape well even after a full day at the office, and the taupe is a genuinely wearable neutral that goes with almost everything in my closet. I got the S and the waist sits comfortably without needing a belt, though the wool blend does mean I have to be careful about ironing temperature. Drape through the leg is soft rather than stiff, which I wasn''t sure about from photos alone.','2026-01-21T09:26:14Z'),
    ('demo-review-12-002@shopupu.local','Fiona Doyle',12,4,'Ordered my usual M and the length is perfect with low heels, but the waistband has a little extra room even with the pleats gathered. Not enough to size down for, just noting it. Fabric feels more expensive than the price suggests, soft wool blend with a slight structure to it.','2026-02-04T14:12:39Z'),
    ('demo-review-12-003@shopupu.local','grace_office',12,3,'The wool blend feels good against the skin and the taupe color matched what I saw online. My complaint is the pleats lose their crisp look after sitting for a couple hours, so I find myself pressing them before most wears. Fit in the L was true to size through the hip.','2026-02-16T19:48:02Z'),
    ('demo-review-12-004@shopupu.local','Beata M.',12,5,'Flattering silhouette, taupe reads warm not grey.','2026-02-27T08:03:51Z'),
    ('demo-review-12-005@shopupu.local','Ivana_returns',12,5,'I own two other wide-leg trousers from other stores and these have the best waist construction of the three, the pleats actually stay put through movement instead of flattening within a week. Went with my usual M and it matches how the last pair from here fit. Wool blend doesn''t pill after a few wears which was my main worry going in.','2026-03-09T16:33:07Z'),
    ('demo-review-12-006@shopupu.local','Nora Whelan',12,4,'On my feet a lot for work and these move well without feeling restrictive at the hip. Sized up to L since I prefer a looser waist and that ended up being the right call for me, would be slightly small in M. Pockets are deep enough to actually hold my phone, which is rare for trousers like this.','2026-03-19T11:57:44Z'),
    ('demo-review-12-007@shopupu.local','wardrobe_edit',12,5,'Soft, drapes nicely, true to size for me.','2026-03-28T20:41:12Z'),
    ('demo-review-12-008@shopupu.local','Delia Kowalczyk',12,1,'I usually wear a M comfortably in wide-leg trousers from other brands and this M was noticeably tight through the waist, could not sit down without the pleats pulling open awkwardly. The fabric itself felt nice, good weight for a wool blend, but I had to return them for a size that isn''t offered above L. Wish the sizing ran a bit more generous.','2026-04-05T13:29:58Z'),
    ('demo-review-12-009@shopupu.local','Simona Havelkova',12,5,'I read a couple reviews about the pleats not holding and almost skipped this one, but mine in the S have kept their shape through a full work week including a commute by bike. Taupe is a nice muted tone, easy to pair with both black and white tops. Only small thing is the hem sat a touch long so I had it taken up half an inch.','2026-04-14T10:15:36Z'),
    ('demo-review-12-010@shopupu.local','Petronela V.',12,4,'Comfortable wide leg that still looks put together for the office. Bought the M and it''s true to size, though the wool blend means dry cleaning only which I didn''t realize until I checked the label. Otherwise no complaints, the color is accurate to the listing photos.','2026-04-24T17:02:29Z'),
    ('demo-review-12-011@shopupu.local','amelia_shops',12,3,'The XS fit through the waist but felt roomy at the hip, more of a straight drape than fitted. Fabric is okay, not particularly warm despite being wool blend. Price felt a little high for what arrived, I''d wait for a sale before buying again.','2026-05-11T21:38:47Z'),
    ('demo-review-12-012@shopupu.local','Bridget O''Sullivan',12,5,'Bought these for my mother as a birthday gift since she loves a wide leg trouser for church and family events. She said the taupe photographs beautifully and the pleats give a nice structured look without being stiff. Went with L based on her usual size and she confirmed the waist has just enough give to sit comfortably after a meal, which she appreciated.','2026-05-28T12:44:09Z'),
    ('demo-review-12-013@shopupu.local','Zuzana Balogova',12,5,'M fits close to true to size, maybe a touch loose at the waistband but nothing a thin belt doesn''t fix instantly. What sold me is the fabric weight, heavy enough to hold the pleat shape but not stiff or scratchy against tights. Delivery arrived a couple days later than the estimate, package was a little creased, but the trousers themselves were fine once hung up overnight.','2026-06-19T15:20:52Z'),
    ('demo-review-13-001@shopupu.local','Radek Prochazka',13,5,'Got the M for weekend hikes and yard work, the ripstop cotton has taken some real abuse without tearing at the knee or pocket seams. Olive color is close to the listing, maybe a shade greener in direct sun. Six pockets are all genuinely usable, not decorative, which is rare these days.','2026-01-18T08:47:33Z'),
    ('demo-review-13-002@shopupu.local','Lukas Bartos',13,4,'Sized up to L from my usual M for extra room in the thigh and that was the right move, still true to size through the waist though. The cargo pockets sit a little lower than I expected so they catch on car seats sometimes, minor gripe. Fabric is breathable enough for warmer days.','2026-01-29T14:03:16Z'),
    ('demo-review-13-003@shopupu.local','cargo_dad_88',13,3,'The waist fit fine in a S but the inseam is long enough that I need to cuff them or get them hemmed, similar issue to other cargo styles I''ve bought. Olive color is accurate. The extra thigh pocket is handy for keeping my phone off my back pocket. Decent overall, just not a perfect out-of-box fit.','2026-02-08T19:22:51Z'),
    ('demo-review-13-004@shopupu.local','Denys K.',13,5,'Sturdy, comfortable, olive is a nice muted tone.','2026-02-17T09:15:04Z'),
    ('demo-review-13-005@shopupu.local','Bohdan_reorders',13,5,'I''ve gone through two other cargo pants from other brands and both wore thin at the knee within months, these are still solid after regular use for yard work and dog walks. Got the L, roomy through the leg but the waistband has a drawstring cinch so it doesn''t feel sloppy. Ripstop weave feels genuinely heavier duty than most fast fashion cargos.','2026-03-02T12:38:47Z'),
    ('demo-review-13-006@shopupu.local','Andrii Melnyk',13,4,'Went with XL and it fits comfortably loose without looking baggy, which is what I wanted for a relaxed style. One of the snap buttons on a side pocket felt a little loose out of the box, hasn''t come off yet but I''m keeping an eye on it. Otherwise happy with the purchase.','2026-03-12T16:54:19Z'),
    ('demo-review-13-007@shopupu.local','trailmode',13,5,'True to size in M, comfortable for daily wear, would buy again.','2026-03-24T21:07:38Z'),
    ('demo-review-13-008@shopupu.local','Teodor S.',13,1,'Normally a S fits me fine in relaxed cargo styles but this one felt more like a fitted cut through the waist, could not sit comfortably for more than an hour. Fabric quality is fine, olive color matched the photos, but the actual cut was nothing like relaxed for me. Ended up returning for a refund since L was sold out.','2026-04-03T10:41:22Z'),
    ('demo-review-13-009@shopupu.local','Vitalii Bondar',13,5,'Wasn''t sure ripstop cotton would feel soft enough for everyday wear but it''s actually broken in nicely after a few washes without losing shape. M was true to size for me, drawstring waist helps if you''re between sizes. Only small thing is the color came out slightly darker than the online photo suggested, more of a deep olive than sage.','2026-04-13T13:29:04Z'),
    ('demo-review-13-010@shopupu.local','Roksolana P.',13,4,'Movement is unrestricted even in a deep squat, which surprised me for cargo-style pants. Went with M and it sits true to size at the waist, maybe a touch snug if you''re carrying stuff in the side pockets. Breathable fabric held up through a sweaty workout without clinging.','2026-04-22T18:16:53Z'),
    ('demo-review-13-011@shopupu.local','Marcus Byrne',13,2,'The olive shown online looked more khaki-green, what arrived is closer to a drab military tone which isn''t really my style. Fit itself was okay in L, true to size, no complaints on cut or fabric weight. Just disappointed by the color mismatch since that was the main reason I picked this pair.','2026-05-05T11:33:47Z'),
    ('demo-review-13-012@shopupu.local','Halyna Kravets',13,5,'Ordered the M as a surprise for my son who lives in cargo pants for skating and hanging out with friends. He confirmed they fit true to size and said the fabric feels tougher than his other pairs, already scuffed one pocket on concrete with no visible damage. Easy wash care too which matters since he''s not gentle with clothes.','2026-05-17T09:52:11Z'),
    ('demo-review-13-013@shopupu.local','kostya.wears',13,5,'Comfy for work shifts on my feet all day, olive looks good with basically any shirt I own. L is roomy but not falling off, cinches at the waist nicely. Will probably grab a second pair before summer.','2026-05-30T20:24:36Z'),
    ('demo-review-13-014@shopupu.local','Yaroslav_orders',13,4,'Fabric is a heavier ripstop than I expected for the price, holds a crease along the front which I like. Ordered M, arrived true to size through the waist and thigh. Only knock is delivery took about four extra days past the estimate, package itself was undamaged when it showed up.','2026-06-10T07:18:59Z'),
    ('demo-review-13-015@shopupu.local','Bartholomew Quinn',13,5,'I compared the stitching on these to a pricier brand I already own and honestly the difference is minor, double stitching on the pocket flaps and a reinforced seat panel that most budget cargos skip. XL fits with room to layer a base layer underneath for colder days without feeling restrictive. Olive color held up fine through two washes, no fading around the pocket edges where I expected it most.','2026-06-27T14:41:27Z'),
    ('demo-review-14-001@shopupu.local','Renata Kovacs',14,5,'The satin viscose has real weight to it, not the flimsy kind that clings to tights. I''m 5''6" and it hits right at mid-calf like the photos show. Black is a true black too, no weird sheen under office lighting.','2026-01-19T08:14:22Z'),
    ('demo-review-14-002@shopupu.local','j.torres',14,4,'Ordered my usual size and the high waist sits fine but there''s a bit of extra room, I might''ve needed the S instead. Fabric itself is lovely and the A-line shape doesn''t add bulk at the hips. Would still buy again, just size down if you''re in between.','2026-02-02T19:41:07Z'),
    ('demo-review-14-003@shopupu.local','Amelia Ferris',14,5,'Wasn''t expecting much from a satin skirt at this price but the stitching along the waistband is clean and there''s no visible puckering. Wore it with a simple tank and boots and got two compliments at work.','2026-02-11T14:03:55Z'),
    ('demo-review-14-004@shopupu.local','Diane P.',14,3,'It looked smooth in the product photos but after sitting in it for a couple hours the front is noticeably wrinkled. Doesn''t fall out on its own, I have to iron it low heat before wearing again. Fit and length are fine, just wish the fabric held its shape better through the day.','2026-02-20T11:27:38Z'),
    ('demo-review-14-005@shopupu.local','hana.k',14,4,'Easy to dress up or down. Zipper on the side takes a little wiggling to get past the hip, loosens up after a few wears though.','2026-03-01T20:09:14Z'),
    ('demo-review-14-006@shopupu.local','Anika R.',14,5,'She wears a size M usually so I went with that and it fit her well when she tried it on. Came folded in tissue paper which felt a bit more thoughtful than a plain poly bag. She''s already asked where I got it so I''d call that a win.','2026-03-09T16:48:29Z'),
    ('demo-review-14-007@shopupu.local','Yeva Solovey',14,4,'The satin has a nice heavy drape and doesn''t wrinkle as badly as some I''ve owned. I''d say the waist runs slightly small, I could feel it after a big lunch. Length was exactly as described for my height, hits mid-calf.','2026-03-15T10:52:41Z'),
    ('demo-review-14-008@shopupu.local','brooke_m',14,5,'Comfortable and true to size, no complaints.','2026-03-22T07:36:18Z'),
    ('demo-review-14-009@shopupu.local','Sofia B.',14,3,'I''m on the taller side and expected this to sit closer to my ankle based on the model photos, but it lands a good few inches above where I wanted for a proper midi. The satin quality itself is decent for the price and the color is accurate. Might work better for someone under 5''5".','2026-03-30T13:19:52Z'),
    ('demo-review-14-010@shopupu.local','Callum Reyes',14,4,'This is my third satin skirt from different stores and honestly the drape on this one is closer to the pricier brands than I expected. Pairs well with a plain white shirt tucked in, or a fitted sweater in cooler weather. One small thing, the inner lining bunches a little when I sit down for long periods, not a dealbreaker.','2026-04-05T21:14:03Z'),
    ('demo-review-14-011@shopupu.local','Marguerite Yun',14,5,'This is such a good basic. Goes with sneakers for daytime or heels for evening, doesn''t feel like it''s trying too hard either way. The elastic panel at the back waist means it''s still comfortable after a full day, which I wasn''t expecting from something this structured looking.','2026-04-14T18:27:46Z'),
    ('demo-review-14-012@shopupu.local','Whitney Doran',14,1,'The satin feels closer to a lining fabric than something meant to be worn as the outer layer, and you can see panty lines through it under bright light. Waist was also loose even in my normal size. Returning this one, disappointed since the photos looked much more substantial.','2026-04-23T09:58:12Z'),
    ('demo-review-14-013@shopupu.local','kayla.mtz',14,5,'arrived way faster than i expected, like 3 days. skirt itself is gorgeous, the black has a subtle sheen without looking cheap or shiny under normal light. wearing it to a dinner this weekend and honestly kind of excited about it lol','2026-05-02T22:11:37Z'),
    ('demo-review-14-014@shopupu.local','Nadia Sultani',14,4,'For what it costs I think this is a solid piece, feels more expensive than the tag suggests. One thing I''d mention is it needs a delicate wash cycle or the satin starts to lose its smoothness fast, learned that the hard way after washing it with regular clothes the first time.','2026-05-19T15:44:29Z'),
    ('demo-review-15-001@shopupu.local','Ingrid Halvorsen',15,5,'The wrap sits flat against the body without pulling at the chest, which is rare for me since I''m on the smaller side up top. Burgundy is deep and rich, not the orange-red some photos make wrap dresses look like. Sleeves are long enough to cover my wrists too.','2026-01-17T09:22:14Z'),
    ('demo-review-15-002@shopupu.local','d.okafor',15,4,'This is genuinely one of the comfiest dresses I own, feels like wearing a sweatshirt but looks put together. Only thing is the tie sits a little higher than my natural waist so I adjusted it lower for a better silhouette. Fabric hasn''t pilled after three washes.','2026-01-26T20:07:39Z'),
    ('demo-review-15-003@shopupu.local','Beatrix Lund',15,5,'Wasn''t sure about ordering a wrap dress online since fit is so particular but this one worked out. The jersey has good stretch without feeling cheap, and the V-neck isn''t as deep as it looked in the photos so it''s actually office appropriate.','2026-02-04T13:45:02Z'),
    ('demo-review-15-004@shopupu.local','Rosalind T.',15,3,'The dress looks great standing up but when I sit down the wrap front tends to shift and gap slightly at the chest, so I''ve started wearing a cami underneath just in case. Fabric quality is nice and soft, length is right at the knee which I like. It''s fine, just not as secure as I''d hoped for something I want to wear all day.','2026-02-13T17:31:56Z'),
    ('demo-review-15-005@shopupu.local','malik_r',15,4,'Long sleeves make this actually wearable into cooler months instead of just summer. Jersey is soft against skin, no itch at all. Runs slightly large in my opinion so I''d size down if unsure.','2026-02-21T22:18:47Z'),
    ('demo-review-15-006@shopupu.local','tia.w',15,5,'Comfy, good color, would order again.','2026-03-02T08:53:29Z'),
    ('demo-review-15-007@shopupu.local','Andres Klimek',15,4,'Picked the M based on her usual size in similar brands and it fit her well through the shoulders and waist. She mentioned the fabric is a little thinner than she expected but says it drapes nicely regardless and she''s already worn it twice this month.','2026-03-10T19:04:15Z'),
    ('demo-review-15-008@shopupu.local','Naomi Frisch',15,5,'I can go straight from the office to dinner in this without changing, which is exactly what I wanted. The midi length is modest enough for meetings and the wrap tie can be adjusted throughout the day if it loosens.','2026-03-18T11:39:52Z'),
    ('demo-review-15-009@shopupu.local','Carmen Dziewulska',15,3,'After being packed for shipping it took a full day hanging up before the wrinkles relaxed, and it still creases a bit after sitting in a car seat. Fit itself is true to size and the color matches the listing well. Just wish the jersey held its shape a little better.','2026-03-27T15:22:08Z'),
    ('demo-review-15-010@shopupu.local','Fenwick Osei',15,5,'I own two other wrap dresses and this is now my favorite of the three. The sleeve length is just right, not too tight at the wrist, and the fabric moves with you instead of clinging. Only very minor note is the tie strings are a touch short if you want a bigger bow, but I just wrap it twice around.','2026-04-04T20:47:33Z'),
    ('demo-review-15-011@shopupu.local','briana_vo',15,4,'love the color and the fit is spot on for my usual size but under strong sunlight you can see the outline of a slip underneath, worth knowing before you wear it out. otherwise soft and comfortable all day, no complaints on the stretch or the length','2026-04-12T18:16:41Z'),
    ('demo-review-15-012@shopupu.local','Olusegun A.',15,5,'Soft, fits true to size, no issues so far.','2026-04-21T07:29:04Z'),
    ('demo-review-15-013@shopupu.local','Odalys Fenn',15,1,'The tie at the waist does not hold well and loosened twice within the first hour of wearing it out, which was pretty embarrassing honestly. Fabric feels fine and the burgundy color is nice, but a wrap dress needs to actually stay wrapped. Might try a smaller size next time to see if that helps, but returning this one for now.','2026-05-06T14:52:19Z'),
    ('demo-review-15-014@shopupu.local','Perpetua Almeida',15,5,'The V-neck and wrap style look polished on camera without being fussy to put on. I appreciate that the sleeves are genuinely long sleeve length and not the cropped kind that shows up in some listings. Washed it on cold and it kept its shape fine.','2026-05-15T09:38:56Z'),
    ('demo-review-15-015@shopupu.local','yasmin.b',15,4,'dress is nice, no real complaints there, the jersey feels good and true to size for me. only annoying part was it arrived like four days past the estimate so i almost missed wearing it for the event i bought it for. glad it worked out in the end 🙂','2026-05-28T21:04:37Z'),
    ('demo-review-15-016@shopupu.local','Genevieve Marchetti',15,5,'This dress does a lot of work for how simple it is. The wrap silhouette is flattering without needing shapewear underneath, and the burgundy reads as sophisticated rather than flashy. I wore it to a friend''s engagement dinner and felt properly dressed without being uncomfortable all night. Small thing worth noting, the fabric picked up a tiny bit of lint from my coat on the drive over, easy enough to brush off but I wasn''t expecting jersey to attract it that much.','2026-06-09T16:12:48Z'),
    ('demo-review-16-001@shopupu.local','Marcus Ohlin',16,5,'Been wearing this over button-downs instead of my usual blazer for casual Fridays. The polo collar sits flat and doesn''t curl up during the day. Navy is a true navy, not too blue or too black.','2026-01-16T09:33:41Z'),
    ('demo-review-16-002@shopupu.local','diego_r',16,4,'Cotton-wool blend is comfortable and not scratchy at all. My only note is the buttons feel slightly thin compared to the rest of the construction, hoping they hold up over time.','2026-01-24T17:52:09Z'),
    ('demo-review-16-003@shopupu.local','Tomasz W.',16,5,'She picked the M based on my usual shirt size and it landed perfectly, not tight through the shoulders at all. Wrapped nicely too, came in a simple box that made it feel like a proper gift.','2026-02-06T20:11:38Z'),
    ('demo-review-16-004@shopupu.local','Hannes B.',16,3,'Ordered my usual M and it''s noticeably roomier than expected, especially through the body. Fabric itself is good quality, I just think I''ll need to exchange for a S. Would size down if you''re in between.','2026-02-19T13:04:55Z'),
    ('demo-review-16-005@shopupu.local','Ravi Chandran',16,5,'Light enough that it''s not overkill in mild weather but still has some substance to it. Pairs well with chinos, wore it to two different dinners already and got compliments both times.','2026-03-01T18:47:22Z'),
    ('demo-review-16-006@shopupu.local','j.mercer',16,4,'Solid pick, sleeves are a hair long on me but rolls up fine.','2026-03-10T07:29:14Z'),
    ('demo-review-16-007@shopupu.local','Bogdan Ionescu',16,5,'I was not expecting so much from this price, honestly. The knit is thick in a good way and buttons close smoothly, no struggling with them like some cardigans I own. Sleeve length is correct for my arms and it did not shrink after first wash on cold.','2026-03-22T11:15:47Z'),
    ('demo-review-16-008@shopupu.local','Kwame Asante',16,5,'I throw this on over a tee before and after workouts, doesn''t restrict movement when I''m carrying my bag or reaching for stuff on shelves. Breathes better than I expected for a knit this dense.','2026-04-05T21:38:03Z'),
    ('demo-review-16-009@shopupu.local','Felix Granholm',16,4,'Already own the crewneck sweater and a tee from here so I knew roughly how the sizing runs before I ordered. This one is consistent with those, M fits the same as always, no guessing needed at checkout this time. The cotton-wool blend has a nicer drape than I expected from photos, sits close to the body without clinging, and the polo collar gives it enough structure to wear over a shirt without looking sloppy. Only real complaint is the collar softened up a bit faster than I''d like after a few wears, it doesn''t hold its shape as crisply by the end of the day as it did brand new. Still my favorite piece from the three I''ve bought so far, and I''ll likely pick up the gray version once it''s back in stock.','2026-04-19T14:52:36Z'),
    ('demo-review-16-010@shopupu.local','deadstock_dan',16,3,'not bad but not amazing either, kinda expected the collar to hold shape better tbh. still wear it around the house so its not a waste of money or anything','2026-05-02T16:24:19Z'),
    ('demo-review-16-011@shopupu.local','R. Castellano',16,5,'Comfortable, good navy shade, would buy again.','2026-05-18T10:07:52Z'),
    ('demo-review-16-012@shopupu.local','Klara Novakova',16,4,'The cardigan itself is great, soft collar, fits true to size in a M for me. Just annoyed it arrived four days past the estimate, otherwise no complaints about the product.','2026-06-08T08:41:27Z'),
    ('demo-review-16-013@shopupu.local','Simon Achterberg',16,1,'Ordered a L expecting it to fit like the sizing chart said and it''s way too small across the chest, could barely button it up. Fabric quality seems fine but the fit runs completely different from the sweater I bought here before, so I couldn''t rely on past experience. Returning it.','2026-06-27T19:16:44Z'),
    ('demo-review-17-001@shopupu.local','Freya N.',17,5,'Bought this specifically for the oversized cut and it delivers, drapes well without looking like I grabbed the wrong size by accident. Pale blue is soft and not chalky like some listings show. I sized down to S from my usual M since the whole point is the relaxed fit, and that worked out exactly as hoped.','2026-01-16T10:22:41Z'),
    ('demo-review-17-002@shopupu.local','Casper W.',17,4,'Comfortable oxford weave, good weight for layering over a tee. Ordered my true size M and the sleeves run long even accounting for the oversized style, I end up rolling them most days. Otherwise a solid shirt for the price.','2026-02-03T15:47:19Z'),
    ('demo-review-17-003@shopupu.local','mo.reyes',17,5,'Comfy, roomy, good for layering.','2026-03-09T08:11:03Z'),
    ('demo-review-17-004@shopupu.local','Ingrid B.',17,3,'I know it''s meant to be oversized but even sizing down to S from my usual M, it''s swimming on me a bit more than I wanted. Fabric quality is genuinely nice, good oxford texture and the pale blue looks true to the photos. Might have needed XS instead, my mistake more than the shirt''s.','2026-04-14T19:36:27Z'),
    ('demo-review-17-005@shopupu.local','Aurelia S.',17,5,'We ended up ordering two, one in M for him and one in S for me since it''s unisex sizing and honestly it looks great on both of us, just styled differently. His fits with that boxy relaxed shoulder look, mine is more like a shirt-jacket over leggings. Fabric held up fine through the first wash too, no shrinking that we noticed.','2026-05-19T12:58:44Z'),
    ('demo-review-17-006@shopupu.local','Dax R.',17,4,'Fabric is a bit lighter weight than I expected from an oxford cloth shirt, still nice but not the stiff structured feel I''m used to. Collar in particular is softer and doesn''t hold as crisp a point. Sizing is generous, went with XS for a fitted-oversized look and got exactly that.','2026-01-29T07:04:52Z'),
    ('demo-review-17-007@shopupu.local','Selin K.',17,5,'This has been on repeat since it arrived, open over a plain tank with jeans or buttoned up for something more put together. Pale blue goes with almost everything in my closet already. Runs true to the oversized description in L, plenty of room through the body without looking like a tent.','2026-06-08T21:17:09Z'),
    ('demo-review-17-008@shopupu.local','jt_moreno',17,5,'wasnt expecting much honestly for the price but its held up great through like 6 washes now, no fading no shrink. i got size M and its nice and loose like the pics showed, not too much tho. wear it basically every week now over a hoodie when its cold out lol','2026-02-25T23:41:36Z'),
    ('demo-review-17-009@shopupu.local','Torsten H.',17,2,'The oversized body shape is fine but the sleeves are disproportionately long even for the style, past my wrists by a couple inches in size M which is my usual. Fabric is decent quality, oxford texture is there, but I keep having to push sleeves up which gets old fast. Might exchange for S to see if that helps.','2026-03-17T14:29:58Z'),
    ('demo-review-17-010@shopupu.local','Marisol P.',17,4,'Wears well for a casual office setting, pairs easily with chinos. Color is a touch more gray-blue in person than the bright pale blue shown online, still nice just slightly different. XL fits with room to spare, exactly as expected for the oversized cut.','2026-05-02T09:53:14Z'),
    ('demo-review-17-011@shopupu.local','Une Berg',17,5,'Already had the white and the sage version, added pale blue to the rotation now. Consistent sizing across all three in S for the oversized fit I like, and the stitching on this batch actually looks a touch neater at the cuffs than my older two. If you liked their previous oxfords this one won''t disappoint.','2026-06-21T17:38:22Z'),
    ('demo-review-17-012@shopupu.local','Corinne A.',17,1,'Unfortunately mine came with a faint yellowish mark near the chest pocket that didn''t come out in the wash. Shirt itself would have been fine otherwise, nice drape and the pale blue color matched the site photos well. Contacted support for a replacement, waiting to hear back. Frustrating since I needed it for an event.','2026-04-27T11:06:38Z'),
    ('demo-review-17-013@shopupu.local','Amara D.',17,4,'Very oversized, size down if unsure.','2026-01-24T06:48:29Z'),
    ('demo-review-17-014@shopupu.local','hana_yildiz',17,5,'this shirt very nice for casual look, i buy size M and is oversize how i want, fabric feel little rough first day but after one wash become more soft. color pale blue same like picture on website, not different. sleeve maybe little long but i just fold up, no big problem for me. good value overall i think.','2026-06-30T18:12:47Z'),
    ('demo-review-17-015@shopupu.local','Livia T.',17,5,'I''ve been hunting for an oversized oxford that doesn''t feel like a boxy potato sack and this one nails it, the shoulder seams drop just enough to read as intentional rather than ill-fitting. Fabric has a nice subtle texture up close, breathable enough for warmer days when worn open. I went with XS since I wanted the fit closer to how it''s styled on the model, and that sizing choice worked out well. Only tiny note is the buttons feel a bit lightweight, not flimsy exactly, just not as substantial as I''d expect at this price. Would still buy again in another color.','2026-03-26T20:44:15Z'),
    ('demo-review-18-001@shopupu.local','Bram V.',18,4,'Cycled through a proper downpour last week, stayed completely dry underneath. Hood cinches down well even in wind gusts. Zipper feels a bit cheap though, snags if you rush it.','2026-01-17T07:29:41Z'),
    ('demo-review-18-002@shopupu.local','Anjali R.',18,5,'Slate Teal is a nice muted shade, not as bright as it looks online but I like it more this way. I''m usually a M but ordered L for room to layer a fleece underneath and glad I did, chest was snug in the sample size I tried at a store. Seam taping looks well done inside, no obvious weak points.','2026-01-25T13:52:09Z'),
    ('demo-review-18-003@shopupu.local','reneg_ade',18,5,'Solid rain shell, true to size.','2026-02-01T09:03:15Z'),
    ('demo-review-18-004@shopupu.local','Colm Fitzgerald',18,3,'Does what it says on the box - rain beads right off and I haven''t had any leaks after a few weeks of use. But this is a shell only, basically no insulation, so under about 8C you need something thick underneath or you''ll be cold despite staying dry. Wish that was clearer in the listing.','2026-02-10T18:40:22Z'),
    ('demo-review-18-005@shopupu.local','M. Alderete',18,5,'Wasn''t expecting much given the price point but this holds up well against actual weather, not just drizzle. Wore it hiking a wet trail and the hood has a stiff brim that actually keeps rain off your face instead of just flopping around. Slate Teal color matched the product photos closely.','2026-02-19T11:16:48Z'),
    ('demo-review-18-006@shopupu.local','carmen_daily',18,4,'Just need something for dog walks and errands in bad weather, works great for that. Sleeves run a touch long in the M but I push them up.','2026-03-01T15:24:33Z'),
    ('demo-review-18-007@shopupu.local','Devin R.',18,5,'Perfect running shell, moves with me 🙂','2026-03-09T06:47:12Z'),
    ('demo-review-18-008@shopupu.local','Franziska Huber',18,1,'Started noticing damp patches on the shoulders after about three weeks of regular use, right where the seam lines are. For something marketed as a technical waterproof shell that''s a real problem, not just a minor gripe. Contacted support and I''m mid-return process now, can''t recommend based on what I got.','2026-03-18T20:02:57Z'),
    ('demo-review-18-009@shopupu.local','Jorge Villanueva',18,4,'Great jacket overall, XL gives plenty of room over a hoodie without feeling like a tent. Only downside is the color leans a bit darker teal than the site photo suggested, more of a deep slate blue in daylight. Not a dealbreaker, just noting it for anyone particular about exact shade.','2026-03-29T14:38:05Z'),
    ('demo-review-18-010@shopupu.local','Lindiwe M.',18,5,'Third piece I''ve bought from this store now and they keep the sizing consistent across completely different categories, which I genuinely appreciate after getting burned by inconsistent brands elsewhere. This jacket packs down small enough to stuff in the side pocket of a daypack, which matters a lot when I''m not sure if I''ll need it that day. Seams are taped properly on the inside as far as I can tell without cutting it open, and the zipper pulls have decent grip even when my hands are wet, unlike a cheaper shell I owned a few years back that became nearly impossible to operate in real rain. Only tiny thing worth mentioning is the packaging was just a plain poly bag, nothing fancy, but the jacket itself arrived without a single mark on it so I really can''t complain. Will keep coming back to this store for outerwear.','2026-04-14T09:55:19Z'),
    ('demo-review-18-011@shopupu.local','Alessio B.',18,2,'Ordered my normal M and it''s genuinely swimming on me, more like a L or even XL by the actual measurements. Fabric quality itself is fine, waterproofing seems to work, but I can''t wear this in wind without the whole thing billowing out. Returning to try a size down.','2026-04-27T16:20:44Z'),
    ('demo-review-18-012@shopupu.local','quinn_outside',18,5,'Ordered on a Monday, had it by Thursday, no complaints on delivery. Rain protection is legit, wore it through a storm at a festival and stayed dry the whole time. Slate Teal is a nice color that doesn''t scream outdoor gear.','2026-05-10T12:33:27Z'),
    ('demo-review-18-013@shopupu.local','Ji-woo P.',18,3,'I like the design a lot and the hood is very functional, it protect well from rain on my face even when wind is strong, this was big worry for me before buying. But material is thiner than I expect from a technical jacket description, feels more like light shell than heavy duty one, so maybe not correct for very cold country like where I live. Still it works okay for normal rain days here, just not for real winter storm. Size S was correct for my body, no problem with shoulders or sleeves length, which is different experience than other online stores where I always need to guess wrong size first before getting right one. Color Slate Teal also nice in person, not too flashy for daily use at office. I think is fair jacket for medium climate, just manage expectation about warmth before you buy.','2026-05-23T08:47:53Z'),
    ('demo-review-18-014@shopupu.local','toribio.m',18,4,'not gonna lie i was skeptical for the price but ive worn this like every rainy week since march and its holding up fine. hood stays up in wind which is honestly rare, ive had way pricier jackets fail at that. shoulders were a little tight at first in the M but loosened up after a few wears, no big deal now','2026-06-15T19:11:36Z'),
    ('demo-review-19-001@shopupu.local','Callum Reed',19,5,'Brushed flannel is thick enough to wear alone once the sun goes down but not so heavy it''s a hassle indoors. Cream plaid pattern is subtle, not loud like some flannels I''ve tried. Holds up well after two washes so far.','2026-01-18T15:27:33Z'),
    ('demo-review-19-002@shopupu.local','Yusuf Demir',19,4,'Soft brushed texture and the plaid isn''t overpowering, solid overshirt overall. Had to roll the cuffs since the sleeves sit past my wrists at 5''9", other than that fits how I expected.','2026-01-29T10:12:48Z'),
    ('demo-review-19-003@shopupu.local','Nadia Kovač',19,5,'Got him the L since he''s broad through the shoulders and it fits like it was made for him. He mentioned the collar is softer than his old flannel shirts, in a good way. Easy gift win.','2026-02-10T19:44:02Z'),
    ('demo-review-19-004@shopupu.local','Otis Blackwood',19,5,'Wear it open over a plain tee most days. Goes with jeans easily and works with sneakers or boots. Fabric wrinkles a little if it sits in the dryer too long, but a quick shake out fixes that.','2026-02-22T08:39:16Z'),
    ('demo-review-19-005@shopupu.local','Anton Lindqvist',19,3,'As a standalone shirt it might be true to size, but worn as a layer over anything it gets bulky fast. I ordered M and probably should have gone S given how roomy the body is. Fabric quality is fine, just wish the cut were slimmer.','2026-03-05T14:58:27Z'),
    ('demo-review-19-006@shopupu.local','mira.k',19,4,'Comfortable and warm enough for a chilly office. Buttons were stiff to close for the first few wears but loosened up after washing. Would buy the other colorway too.','2026-03-16T20:21:04Z'),
    ('demo-review-19-007@shopupu.local','Grzegorz Nowak',19,5,'I did not think brushed cotton would feel this soft honestly. Wear it around house on weekends and also outside with jeans, both work good. Cream plaid color is exactly same how it look in photo, no difference.','2026-03-28T12:07:51Z'),
    ('demo-review-19-008@shopupu.local','T. Osei',19,4,'Warm enough for a walk in cool weather without needing a real coat.','2026-04-08T09:15:39Z'),
    ('demo-review-19-009@shopupu.local','Deshawn Carter',19,5,'Keep this in my bag to throw on after a workout when it cools down outside. Doesn''t feel stiff or restrict my arms when I''m packing stuff up. Held up fine through a few sweaty commutes home.','2026-04-21T18:33:12Z'),
    ('demo-review-19-010@shopupu.local','cole_thrifts',19,3,'its ok i guess, wrinkles way more than i thought a flannel would tbh. still looks decent enough thrown over a shirt so keeping it, just annoying to iron every time','2026-05-04T16:49:58Z'),
    ('demo-review-19-011@shopupu.local','Astrid Halvorsen',19,5,'Already have the crewneck sweater from here and this fits the same true-to-size way, no surprises when it arrived. Fabric held its shape after washing on cold and the plaid hasn''t faded at all after a month of regular wear, which matters to me since I tend to wear things into the ground before replacing them. The brushed cotton feels heavier than a standard flannel shirt without tipping into jacket territory, so it works as a mid-layer on cooler mornings and on its own once it warms up in the afternoon. Buttons are sturdy, collar keeps its shape unlike some flannels that go limp after a wash or two. This brand''s sizing has been reliable for me across two different pieces now, so I ordered my usual M again without checking the chart and it worked out exactly as expected.','2026-05-20T11:26:44Z'),
    ('demo-review-19-012@shopupu.local','Beatriz Salgado',19,4,'Came two days early actually, packaging was simple but the shirt was folded neatly with no wrinkles from shipping. Collar is a little softer than a typical flannel collar, works fine for me either way.','2026-06-02T07:58:21Z'),
    ('demo-review-19-013@shopupu.local','hana_wardrobe',19,5,'Layers really well 🙂','2026-06-19T13:42:09Z'),
    ('demo-review-19-014@shopupu.local','Radu Stanescu',19,1,'Ordered a M expecting a standard fit and it''s oversized to the point it looks like I borrowed it from someone bigger, way more than a normal shirt-jacket allowance for layering. On top of that one of the buttons came loose after the first wash. Sending it back for a refund.','2026-07-06T21:11:37Z'),
    ('demo-review-20-001@shopupu.local','Iker Zubiaga',20,5,'Bought the 42 which is my normal EU size and they fit true, no break-in pain in the heel like some leather sneakers give you. The white leather has stayed mostly clean after a month of regular wear, I wipe it down every week or so. Sole has a good bit of cushion for how minimal the design looks.','2026-01-16T10:22:37Z'),
    ('demo-review-20-002@shopupu.local','Beatriz S.',20,4,'First few wears the leather felt stiff around the toe box and I got some rubbing at the back of my ankle, but by wear four or five it softened up and now they''re genuinely comfortable. Sole is a bit stiffer than sneakers I''m used to but that seems to be the tradeoff for the sleek shape. True to size in 41.','2026-01-24T15:47:52Z'),
    ('demo-review-20-003@shopupu.local','riko.wears',20,5,'Good sneaker, true to size, clean white.','2026-02-01T08:14:03Z'),
    ('demo-review-20-004@shopupu.local','Tobias Lindqvist',20,3,'The design is genuinely minimal and pairs with everything, that part I have no complaints about. But my feet are on the wider side and the 42 pinches slightly across the widest part after a few hours walking. If you have wide feet I''d size up half or look elsewhere. Leather quality itself feels decent for the price.','2026-02-09T13:33:19Z'),
    ('demo-review-20-005@shopupu.local','Naomi Ferreira',20,5,'Wasn''t sure about ordering shoes online without trying them on but the sizing chart was accurate and the 40 fits my foot well, no heel slip. The leather has a nice matte finish rather than glossy, looks more expensive than what I paid. Only small thing is one shoe had a slightly looser lace eyelet than the other, not noticeable once laced up.','2026-02-18T09:58:44Z'),
    ('demo-review-20-006@shopupu.local','desmond_c',20,4,'Wears well with jeans or chinos, easy to style with basically anything. Ordered 43 and there''s a touch of extra room at the toe, not bad just noting for anyone between sizes.','2026-02-27T17:12:08Z'),
    ('demo-review-20-007@shopupu.local','Rhys_Trains',20,5,'Wear these for warmups and walking to work, breathe reasonably well for leather and don''t hold odor. Grip is decent on wet pavement, true to size at 42.','2026-03-08T06:40:51Z'),
    ('demo-review-20-008@shopupu.local','Genevieve Aubert',20,1,'The white leather picks up marks incredibly easily, I had visible scuff lines on the toe after wearing them outside twice, and normal cleaning didn''t fully lift them. For a sneaker marketed as a clean minimal look that defeats the purpose fairly quickly. Returning these, disappointed given the price.','2026-03-17T20:29:14Z'),
    ('demo-review-20-009@shopupu.local','Louise T.',20,4,'Got these for my partner''s birthday and had to guess between his usual 42 and 43, ended up going with 42 which worked out fine per his feedback afterward. He says the leather feels sturdy and the white doesn''t look cheap in person like some budget pairs do. Packaging box was a bit dented on arrival but the shoes inside were untouched.','2026-03-27T12:05:36Z'),
    ('demo-review-20-010@shopupu.local','Chiamaka O.',20,5,'I''ve bought sneakers from this store twice before and this pair matches the same quality level I remember from both previous orders, which says something about how carefully they seem to manage manufacturing across batches. Sizing has stayed consistent too, which is honestly rare across shoe brands in general since I''ve had wildly different fits from the same size label elsewhere. Sole is a little stiffer out of the box than my older pair was, maybe a slightly different batch of rubber, but it softened up within about a week of regular wear and now moves closer to what I remember. Leather cleans up nicely with just a damp cloth and a bit of patience, no special products needed so far. At this point I trust their EU sizing enough to buy without measuring my foot again first.','2026-04-12T10:47:29Z'),
    ('demo-review-20-011@shopupu.local','mira.styles',20,5,'Love them, so clean 🙂','2026-04-21T18:33:02Z'),
    ('demo-review-20-012@shopupu.local','Emeka N.',20,2,'Fit was fine, true to size in 42, but the sole barely flexes even after two weeks of regular wear which makes longer walks uncomfortable on the ball of my foot. Expected something closer to a normal sneaker flex given how the listing described comfort. Might work better for people who mostly stand rather than walk a lot.','2026-05-03T15:19:45Z'),
    ('demo-review-20-013@shopupu.local','pavel.runs',20,5,'Ordered Tuesday, on my feet by Friday, no delays. Leather is soft to the touch, not the stiff cheap kind. 43 fit exactly as expected against the size guide.','2026-05-19T11:52:17Z'),
    ('demo-review-20-014@shopupu.local','Ana-Maria V.',20,3,'Shoes look really nice, very clean white and simple like in photo, my friends already ask me where I buy them. But first days was little painful on my heel, need about one week wearing around house before I feel comfortable to wear outside for long time. Also is running a bit narrow I think, I have size 41 normally in most European brands but maybe 42 is better choice here for people with wide foot like me. I clean the white part already two times with just wet cloth and mild soap, so far marks come off easy, this I am happy about. Still good product overall, just need patience at start before shoes feel like they really belong to your foot.','2026-05-30T09:24:58Z'),
    ('demo-review-20-015@shopupu.local','benicio_wears',20,4,'honestly wear these like 4x a week now, go with basically every outfit i own. only thing is the left shoe felt very slightly looser than the right one out of the box, not enough to return over but i noticed it first day. sizing wise the 40 was right for me, true to my usual size in other brands too','2026-06-11T20:07:39Z'),
    ('demo-review-20-016@shopupu.local','L. Fontaine',20,5,'Simple, comfortable, does the job.','2026-07-05T14:41:26Z'),
    ('demo-review-21-001@shopupu.local','Torsten Weis',21,5,'I have a wool sensitivity and this one doesn''t bother me at all, must be a finer knit. The fold sits nicely without collapsing and charcoal goes with basically everything in my closet.','2026-01-16T08:02:33Z'),
    ('demo-review-21-002@shopupu.local','min.j',21,4,'Fit felt tight the first couple wears but it''s relaxed a little with use, sits normal on my head now. Rib knit looks good folded or pulled down long, nice for the price.','2026-01-22T17:44:19Z'),
    ('demo-review-21-003@shopupu.local','Wioletta Grabowski',21,5,'Nothing fancy, just a well made wool beanie that keeps my ears warm on the walk to the train. Charcoal is a true dark grey, not black like some listings show.','2026-01-29T12:31:07Z'),
    ('demo-review-21-004@shopupu.local','cole_b',21,3,'does the job for keeping warm but the knit feels thinner and less premium than i pictured for what i paid. fold stays in place fine though and it hasnt stretched out of shape yet after a few weeks of wear','2026-02-05T19:16:52Z'),
    ('demo-review-21-005@shopupu.local','Delphine Roux',21,5,'He''s picky about hats sitting too high on his head but this one folds down enough to cover his ears properly without looking bulky. Simple packaging but the beanie itself feels well made, he''s worn it every cold morning since.','2026-02-12T09:48:24Z'),
    ('demo-review-21-006@shopupu.local','hugo.t',21,4,'Warm, fits well, no complaints beyond a couple loose fibers I trimmed off after unboxing.','2026-02-18T21:03:11Z'),
    ('demo-review-21-007@shopupu.local','Petronella Vance',21,1,'This is much lighter than the charcoal shown in the photos, closer to a medium heather grey on mine. Wouldn''t have ordered it if I''d known, since I specifically wanted something darker to match a jacket. Warmth is fine, just not what I expected color wise.','2026-02-24T14:27:38Z'),
    ('demo-review-21-008@shopupu.local','Baptiste Onyema',21,5,'I go through a lot of cheap beanies every winter and this is holding up noticeably better after a month of near daily wear. It hasn''t lost shape or started pilling on the fold yet, which is usually where mine fall apart first.','2026-03-03T10:15:47Z'),
    ('demo-review-21-009@shopupu.local','reyna_p',21,4,'package showed up in two days which i wasnt expecting. beanie itself is comfortable and warm, only thing is it sits a touch loose on me and slides back a bit if im moving around a lot outside, might just be my head shape though','2026-03-11T20:39:02Z'),
    ('demo-review-21-010@shopupu.local','Astrid F.',21,5,'Warm, good color, no issues.','2026-03-19T07:52:16Z'),
    ('demo-review-21-011@shopupu.local','Consolata Mbeki',21,5,'This has basically replaced the two other beanies I own since it''s warmer and doesn''t leave that annoying line across my forehead after a few hours. The rib knit has enough stretch that it doesn''t feel tight even over a hood. My only small gripe is a couple of the wool fibers shed onto my dark coat the first couple wears, settled down after that though.','2026-03-26T18:44:29Z'),
    ('demo-review-21-012@shopupu.local','Rutger Van Dam',21,4,'Not much to say beyond that it''s a well fitted, warm beanie in a genuinely dark charcoal. Good gift option too since one size covers most people I''ve given similar hats to before.','2026-04-02T11:08:53Z'),
    ('demo-review-22-001@shopupu.local','Henrietta Solberg',22,5,'I was worried cashmere at this price point would feel thin or synthetic but it''s soft against my neck even with a turtleneck underneath. Camel is warm toned, close to the product photo, and drapes nicely instead of sitting stiff.','2026-01-15T09:41:27Z'),
    ('demo-review-22-002@shopupu.local','p.oyelaran',22,4,'The material feels genuinely soft and warm, no complaints there. I just wish it were a bit longer so I could wrap it twice comfortably, as is it''s more of a single loose drape around the neck.','2026-01-20T18:22:14Z'),
    ('demo-review-22-003@shopupu.local','Emeka Chukwu',22,5,'She''s had cashmere before from more expensive brands and said this one holds up fine in comparison. Came wrapped simply but the scarf itself feels substantial, not thin or flimsy like some gift-priced cashmere I''ve seen.','2026-01-25T14:09:56Z'),
    ('demo-review-22-004@shopupu.local','delia_hw',22,3,'color and softness are nice out of the box but i noticed small pills forming near where it rubs against my coat collar after maybe a week of regular wear. know cashmere pills some naturally but i expected it to take longer than this. still warm and looks fine from a distance','2026-01-31T20:37:03Z'),
    ('demo-review-22-005@shopupu.local','Rasmus Ellefsen',22,5,'Genuinely didn''t think cashmere this soft existed under a certain price bracket. Camel color works with basically every coat I own, black, navy, grey, all of it. Lightweight enough to layer under a jacket without feeling bulky.','2026-02-06T11:53:41Z'),
    ('demo-review-22-006@shopupu.local','vince.a',22,4,'Soft, warm, drapes well. Slightly lighter shade of camel than shown on my screen but not a problem.','2026-02-13T08:14:52Z'),
    ('demo-review-22-007@shopupu.local','Zsofia Palkovics',22,5,'This packs flat enough to keep in my bag during commutes but still keeps my neck warm on the platform waiting for the train. Camel shade photographs slightly lighter than it looks in person, more of a rich tan in daylight.','2026-02-19T16:28:37Z'),
    ('demo-review-22-008@shopupu.local','Cordelia Ashby',22,1,'For cashmere I expected something plusher, this feels closer to a wool blend than what I''ve owned before from other brands. Color is accurate at least. Might just be a lower grade cashmere, disappointing given the material it''s supposed to be.','2026-02-25T13:05:19Z'),
    ('demo-review-22-009@shopupu.local','priya.raman',22,5,'Soft, warm, good color match.','2026-03-02T09:47:22Z'),
    ('demo-review-22-010@shopupu.local','toma_lr',22,4,'ordered on a wednesday and it showed up by friday which was a nice surprise. texture is soft and it doesnt feel itchy against my skin at all. only small thing is a couple loose fibers came off in the box, brushed them away and it was fine after that','2026-03-09T19:33:48Z'),
    ('demo-review-22-011@shopupu.local','Anneliese Brandt',22,5,'I switch between three or four scarves each winter and this camel one gets pulled out most mornings now because it goes with everything and never feels heavy around the neck. The length is enough for a single loose knot or a double wrap if I want more warmth. One tiny thing worth mentioning, the fringe ends have started to fray slightly after regular washing, nothing drastic but I now hand wash it to slow that down.','2026-03-17T21:16:04Z'),
    ('demo-review-22-012@shopupu.local','Bartholomew Nkemdirim',22,5,'Bought this as a birthday gift and the size worked out perfectly for wrapping in a small box. Recipient said it''s softer than a similarly priced scarf she''d bought herself last year, so that''s a good sign for the quality here.','2026-03-24T10:52:31Z'),
    ('demo-review-22-013@shopupu.local','Lachlan Ferreira',22,4,'Soft against the skin and warm enough for most of the winter here without being too heavy. It''s a bit pricier than I''d normally spend on a scarf but the material feels like it justifies it more than the fast fashion ones I''ve had before.','2026-04-01T17:29:15Z')
),
ins_users as (
  insert into users (email, password_hash, username, enabled, email_verified)
  select email, '!synthetic-review-author-no-login!', username, true, true
  from seed
  on conflict do nothing
  returning id, email
),
resolved as (
  select s.product_id, s.rating, s.body, s.created_at,
         coalesce(iu.id, u.id) as user_id
  from seed s
  left join ins_users iu on iu.email = s.email
  left join users     u  on u.email  = s.email
)
insert into reviews (user_id, product_id, order_id, rating, body, status, created_at, updated_at)
select user_id, product_id, null, rating, body, 'APPROVED',
       created_at::timestamptz, created_at::timestamptz
from resolved
on conflict (user_id, product_id) do nothing;

commit;
